export const EXAMPLE_SOURCES: readonly { file: string; source: string }[] = [
 {
  "file": "ai_before_after.storelib",
  "source": "{# example\ntitle: Before and after slider\nsummary: Two of the creator's own photos on top of each other with a real range input as the handle, so it works by mouse, touch and arrow keys; a tiny sandboxed script moves the split, and without it the slider still shows both halves at the middle.\ntags: before after, comparison, slider, range, image compare, renovation, results, script\n#}\n<template>\n<section class=\"ba\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <h2 class=\"ba__h\">{{ settings.heading }}</h2>\n  {% if settings.before and settings.after %}\n  <figure class=\"ba__fig\" style=\"--pos: {{ settings.start }}%;\">\n    <img class=\"ba__img\" src=\"{{ settings.after | asset }}\" alt=\"{{ settings.after_alt }}\" width=\"1600\" height=\"1000\">\n    <img class=\"ba__img ba__img--before\" src=\"{{ settings.before | asset }}\" alt=\"{{ settings.before_alt }}\" width=\"1600\" height=\"1000\">\n    <span class=\"ba__line\" aria-hidden=\"true\"></span>\n    <input class=\"ba__range\" type=\"range\" min=\"0\" max=\"100\" value=\"{{ settings.start }}\" aria-label=\"{{ settings.handle_label }}\">\n    <figcaption class=\"ba__cap\"><span>{{ settings.before_label }}</span><span>{{ settings.after_label }}</span></figcaption>\n  </figure>\n  {% elsif page.in_editor %}\n  <p class=\"ba__empty\">Pick a before and an after photo in the sidebar. The slider shows only when both are set.</p>\n  {% endif %}\n</section>\n</template>\n\n<style scoped>\n.ba { padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.ba__h { margin: 0 0 24px; max-width: 20ch; font-family: var(--theme-font-heading), serif; font-size: clamp(1.75rem, 1.2rem + 2.4vw, 3.25rem); line-height: 1; letter-spacing: -0.02em; font-weight: 500; color: var(--s-heading); }\n.ba__fig { position: relative; margin: 0; overflow: hidden; }\n.ba__img { display: block; width: 100%; height: auto; aspect-ratio: 16 / 10; object-fit: cover; }\n.ba__img--before { position: absolute; inset: 0; height: 100%; clip-path: inset(0 calc(100% - var(--pos, 50%)) 0 0); }\n.ba__line { position: absolute; top: 0; bottom: 0; left: var(--pos, 50%); width: 2px; margin-left: -1px; background: var(--s-bg); pointer-events: none; }\n.ba__range { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: ew-resize; }\n.ba__range:focus-visible + .ba__cap { outline: 2px solid var(--s-accent); outline-offset: 4px; }\n.ba__cap { display: flex; justify-content: space-between; padding-top: 10px; font-size: 0.9375rem; font-weight: 500; }\n.ba__empty { opacity: 0.7; }\n</style>\n\n<script>\n/* The range is real, so keys and touch already move it; this only paints the split where it is. */\nconst fig = root.querySelector(\".ba__fig\")\nconst range = root.querySelector(\".ba__range\")\nif (fig && range) {\n  range.addEventListener(\"input\", function (e) {\n    const v = Math.max(0, Math.min(100, Number(e.target.value) || 0))\n    fig.style.setProperty(\"--pos\", v + \"%\")\n  })\n}\n</script>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_before_after\",\n  \"name\": \"Before and after\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"The kitchen on Alma Road\" },\n    { \"type\": \"image_picker\", \"id\": \"before\", \"label\": \"Before photo\" },\n    { \"type\": \"text\", \"id\": \"before_alt\", \"label\": \"Before photo description\", \"default\": \"\" },\n    { \"type\": \"image_picker\", \"id\": \"after\", \"label\": \"After photo\" },\n    { \"type\": \"text\", \"id\": \"after_alt\", \"label\": \"After photo description\", \"default\": \"\" },\n    { \"type\": \"text\", \"id\": \"before_label\", \"label\": \"Before label\", \"default\": \"Before\" },\n    { \"type\": \"text\", \"id\": \"after_label\", \"label\": \"After label\", \"default\": \"After\" },\n    { \"type\": \"text\", \"id\": \"handle_label\", \"label\": \"Slider name (read aloud)\", \"default\": \"Drag to compare before and after\" },\n    { \"type\": \"range\", \"id\": \"start\", \"label\": \"Starting point\", \"min\": 10, \"max\": 90, \"step\": 5, \"unit\": \"%\", \"default\": 50 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_counters.storelib",
  "source": "{# example\ntitle: Counters from real numbers\nsummary: Figures that count up as they scroll into view, with CSS only (@property and a view timeline); each number is one the creator typed in, the section draws nothing for a figure left empty, and the real value is always the text a screen reader and a search engine get.\ntags: counters, stats, numbers, count up, figures, facts, @property, view-timeline\n#}\n<template>\n<section class=\"ct\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  {% if settings.heading %}<h2 class=\"ct__h\">{{ settings.heading }}</h2>{% endif %}\n  <dl class=\"ct__list\">\n    {% for block in section.blocks %}\n      {% if block.settings.value != 0 %}\n      <div class=\"ct__item\" data-block-id=\"{{ block.id }}\">\n        <dt class=\"ct__label\">{{ block.settings.label }}</dt>\n        <dd class=\"ct__value\" style=\"--to: {{ block.settings.value | round }};\"><span class=\"ct__real\">{{ block.settings.value }}{{ block.settings.suffix }}</span><span class=\"ct__anim\" aria-hidden=\"true\">{{ block.settings.suffix }}</span></dd>\n      </div>\n      {% elsif page.in_editor %}\n      <p class=\"ct__empty\">A figure with no number, or 0, is not shown. Type a number you can stand behind.</p>\n      {% endif %}\n    {% endfor %}\n  </dl>\n</section>\n</template>\n\n<style scoped>\n@property --ct-n { syntax: \"<integer>\"; inherits: false; initial-value: 0; }\n.ct { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.ct__h { margin: 0 0 28px; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2.25rem); font-weight: 600; letter-spacing: -0.01em; line-height: 1.1; color: var(--s-heading, var(--s-text)); }\n.ct__list { display: grid; gap: 0; margin: 0; }\n.ct__item { display: flex; flex-direction: column-reverse; gap: 6px; padding: 20px 0; border-top: 1px solid var(--s-border); }\n.ct__label { font-size: 0.9375rem; line-height: 1.4; }\n.ct__value { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(3rem, 1.6rem + 6vw, 7.5rem); line-height: 0.9; letter-spacing: -0.04em; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--s-heading); }\n.ct__anim { display: none; }\n.ct__empty { opacity: 0.7; }\n@container (min-width: 760px) { .ct__list { grid-template-columns: repeat(auto-fit, minmax(min(220px, 100%), 1fr)); gap: 0 32px; } }\n/* Counting is an extra: where the browser can animate an integer on scroll and motion is welcome. The real text stays for assistive tech. */\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .ct__real { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }\n    .ct__anim { display: inline; counter-reset: ct var(--ct-n); animation: ct-count linear both; animation-timeline: view(); animation-range: entry 10% cover 45%; }\n    .ct__anim::before { content: counter(ct); }\n    @keyframes ct-count { from { --ct-n: 0; } to { --ct-n: var(--to); } }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_counters\",\n  \"name\": \"Figures\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"In numbers\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 64 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 64 }\n  ],\n  \"blocks\": [\n    { \"type\": \"figure\", \"name\": \"Figure\", \"limit\": 6, \"min_blocks\": 0, \"settings\": [\n      { \"type\": \"number\", \"id\": \"value\", \"label\": \"Number (a real one; empty hides it)\" },\n      { \"type\": \"text\", \"id\": \"suffix\", \"label\": \"After the number\", \"default\": \"\" },\n      { \"type\": \"text\", \"id\": \"label\", \"label\": \"What it counts\", \"default\": \"Loaves baked this week\" }\n    ] }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_cursor_tilt.storelib",
  "source": "{# example\ntitle: Cursor-aware tilt\nsummary: One showcase picture (a product, a cover, a piece of work) that tilts a few degrees toward the pointer, with nine CSS hover zones and :has() instead of a pointer-tracking script (a section script cannot read the pointer's position); only on a pointer that hovers, flat on touch and under reduced motion, tilt and on or off editable.\ntags: cursor, cursor aware, pointer, tilt, depth tilt, 3d, hover, showcase, product, cover, has, motion tier\n#}\n<template>\n<section class=\"tl\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-btn-bg: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px; --tl-max: {{ settings.tilt }}deg;\">\n  <div class=\"tl__in\">\n    <div class=\"tl__stage\">\n      <div class=\"tl__card\">\n        {% if settings.image %}<img class=\"tl__img\" src=\"{{ settings.image | asset }}\" alt=\"{{ settings.image_alt }}\" width=\"1200\" height=\"1200\" loading=\"lazy\">{% elsif page.in_editor %}<p class=\"tl__ph\">Pick the picture to show in the sidebar</p>{% endif %}\n      </div>\n      <div class=\"tl__zones\" aria-hidden=\"true\"><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span><span class=\"tl__z\"></span></div>\n    </div>\n    <div class=\"tl__copy\">\n      {% if settings.heading %}<h2 class=\"tl__h\">{{ settings.heading }}</h2>{% endif %}\n      {% if settings.text %}<p class=\"tl__text\">{{ settings.text }}</p>{% endif %}\n      {% if settings.cta_label and settings.cta_url %}<a class=\"tl__cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}\n    </div>\n  </div>\n</section>\n</template>\n\n<style scoped>\n.tl { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.tl__in { max-width: var(--theme-page-width, 1280px); margin: 0 auto; display: grid; gap: clamp(28px, 5vw, 72px); align-items: center; }\n.tl__stage { position: relative; perspective: 1000px; max-width: 560px; width: 100%; justify-self: center; }\n.tl__card { aspect-ratio: 1; overflow: hidden; background: color-mix(in srgb, var(--s-text) 8%, var(--s-bg)); --rx: 0; --ry: 0; }\n.tl__img { display: block; width: 100%; height: 100%; object-fit: cover; }\n.tl__ph { display: grid; place-items: center; height: 100%; margin: 0; padding: 16px; text-align: center; opacity: 0.7; }\n.tl__zones { display: none; }\n.tl__h { margin: 0 0 14px; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.9rem, 1.2rem + 2.6vw, 3.6rem); line-height: 1; letter-spacing: -0.03em; font-weight: 700; color: var(--s-heading); }\n.tl__text { margin: 0; max-width: 44ch; font-size: 1.0625rem; line-height: 1.6; }\n.tl__cta { display: inline-flex; align-items: center; min-height: 48px; margin-top: 24px; padding: 0 24px; background: var(--s-btn-bg); color: var(--s-btn-text); text-decoration: none; font-weight: 600; border-radius: var(--t-radius-sm, 2px); }\n.tl__cta:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n@container (min-width: 820px) { .tl__in { grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); } }\n/*\n  The tilt: nine invisible zones over the picture; the one under the pointer\n  sets which way it leans. Only on a pointer that hovers and when motion is\n  welcome; the zones are not even drawn otherwise, so touch gets the picture.\n*/\n@media (prefers-reduced-motion: no-preference) and (hover: hover) and (pointer: fine) {\n  .tl:not([data-motion=\"off\"]) .tl__zones { display: grid; grid-template: repeat(3, 1fr) / repeat(3, 1fr); position: absolute; inset: 0; }\n  .tl:not([data-motion=\"off\"]) .tl__card { transform: rotateX(calc(var(--rx) * var(--tl-max, 4deg))) rotateY(calc(var(--ry) * var(--tl-max, 4deg))); transition: transform calc(var(--t-motion-hover, 200ms) * 2) var(--t-motion-ease-ui, cubic-bezier(0.3, 0.7, 0.4, 1)); }\n  .tl__stage:has(.tl__z:nth-child(1):hover) .tl__card { --rx: 1; --ry: -1; }\n  .tl__stage:has(.tl__z:nth-child(2):hover) .tl__card { --rx: 1; --ry: 0; }\n  .tl__stage:has(.tl__z:nth-child(3):hover) .tl__card { --rx: 1; --ry: 1; }\n  .tl__stage:has(.tl__z:nth-child(4):hover) .tl__card { --rx: 0; --ry: -1; }\n  .tl__stage:has(.tl__z:nth-child(6):hover) .tl__card { --rx: 0; --ry: 1; }\n  .tl__stage:has(.tl__z:nth-child(7):hover) .tl__card { --rx: -1; --ry: -1; }\n  .tl__stage:has(.tl__z:nth-child(8):hover) .tl__card { --rx: -1; --ry: 0; }\n  .tl__stage:has(.tl__z:nth-child(9):hover) .tl__card { --rx: -1; --ry: 1; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_cursor_tilt\",\n  \"name\": \"Picture that leans toward you\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" },\n    { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Picture description\", \"default\": \"\" },\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Dust Tapes, volume two\" },\n    { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"Forty drum loops recorded on a four track in a garage in Margate.\" },\n    { \"type\": \"text\", \"id\": \"cta_label\", \"label\": \"Button\", \"default\": \"Listen and buy\" },\n    { \"type\": \"url\", \"id\": \"cta_url\", \"label\": \"Button link\", \"default\": \"/about\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Leans toward the pointer\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"tilt\", \"label\": \"How far it leans\", \"min\": 0, \"max\": 10, \"step\": 1, \"unit\": \"deg\", \"default\": 4 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_faq_accordion.storelib",
  "source": "{# example\ntitle: Accordion FAQ\nsummary: Questions as details and summary, one open at a time through the name attribute, a smooth height change where the browser supports ::details-content, keyboard and screen reader behaviour from the browser itself.\ntags: faq, accordion, details, summary, questions, disclosure, expandable, syllabus\n#}\n<template>\n<section class=\"fq\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <div class=\"fq__in\">\n    <h2 class=\"fq__h\">{{ settings.heading }}</h2>\n    <div class=\"fq__list\">\n      {% for block in section.blocks %}\n        <details class=\"fq__item\" data-block-id=\"{{ block.id }}\"{% if settings.one_open %} name=\"fq-{{ section.id }}\"{% endif %}{% if forloop.first and settings.open_first %} open{% endif %}>\n          <summary class=\"fq__q\"><span>{{ block.settings.question }}</span><span class=\"fq__mark\" aria-hidden=\"true\"></span></summary>\n          <div class=\"fq__a\">{{ block.settings.answer }}</div>\n        </details>\n      {% else %}\n        {% if page.in_editor %}<p class=\"fq__empty\">Add questions in the sidebar</p>{% endif %}\n      {% endfor %}\n    </div>\n  </div>\n</section>\n</template>\n\n<style scoped>\n.fq { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); interpolate-size: allow-keywords; }\n.fq__in { display: grid; gap: 24px; }\n.fq__h { margin: 0; font-family: var(--theme-font-heading), serif; font-size: clamp(1.75rem, 1.2rem + 2.4vw, 3rem); line-height: 1; letter-spacing: -0.02em; font-weight: 500; color: var(--s-heading); }\n.fq__item { border-top: 1px solid var(--s-border); }\n.fq__item:last-child { border-bottom: 1px solid var(--s-border); }\n.fq__q { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 44px; padding: 18px 0; cursor: pointer; list-style: none; font-size: 1.0625rem; font-weight: 600; color: var(--s-heading); }\n.fq__q::-webkit-details-marker { display: none; }\n.fq__q::marker { content: \"\"; }\n.fq__q:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n.fq__mark { position: relative; flex: none; width: 14px; height: 14px; }\n.fq__mark::before, .fq__mark::after { content: \"\"; position: absolute; inset: 0; margin: auto; background: currentColor; }\n.fq__mark::before { width: 14px; height: 1.5px; }\n.fq__mark::after { width: 1.5px; height: 14px; transition: transform 180ms ease; }\n.fq__item[open] .fq__mark::after { transform: scaleY(0); }\n.fq__a { max-width: 62ch; padding: 0 0 20px; font-size: 1rem; line-height: 1.65; }\n.fq__empty { opacity: 0.7; }\n@container (min-width: 820px) { .fq__in { grid-template-columns: 5fr 7fr; gap: 48px; align-items: start; } .fq__h { position: sticky; top: 96px; } }\n@media (prefers-reduced-motion: no-preference) {\n  .fq__item::details-content { block-size: 0; overflow: clip; transition: block-size 260ms ease, content-visibility 260ms allow-discrete; }\n  .fq__item[open]::details-content { block-size: auto; }\n}\n@media (prefers-reduced-motion: reduce) { .fq__mark::after { transition: none; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_faq_accordion\",\n  \"name\": \"Questions\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Before your first class\" },\n    { \"type\": \"checkbox\", \"id\": \"one_open\", \"label\": \"One answer open at a time\", \"default\": true },\n    { \"type\": \"checkbox\", \"id\": \"open_first\", \"label\": \"Open the first answer\", \"default\": true },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 }\n  ],\n  \"blocks\": [\n    { \"type\": \"question\", \"name\": \"Question\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"question\", \"label\": \"Question\", \"default\": \"What should I bring?\" },\n      { \"type\": \"textarea\", \"id\": \"answer\", \"label\": \"Answer\", \"default\": \"Write the answer people ask you for most.\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Questions\", \"blocks\": [{ \"type\": \"question\", \"settings\": { \"question\": \"What should I bring?\" } }, { \"type\": \"question\", \"settings\": { \"question\": \"Can I come as a complete beginner?\" } }, { \"type\": \"question\", \"settings\": { \"question\": \"How do I cancel a booking?\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_gradient_marquee.storelib",
  "source": "{# example\ntitle: Living gradient band with a scroll-reactive marquee (motion islands)\nsummary: A dark band whose background is a slow grainy shader gradient in the site's own colours (the webgl-gradient motion island) carrying a statement and a giant running line of real words that speeds up with the scroll and turns with its direction (the marquee island); still CSS colours and a wrapped line for reduced motion, low-power phones and no WebGL.\ntags: webgl, shader, gradient, gradient background, living gradient, mesh gradient, velocity marquee, scroll reactive, giant type, software, saas, music, launch, motion islands\n#}\n<template>\n<section class=\"gm\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-btn-bg: {{ scheme.primary_btn_bg }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\" data-storelib-motion=\"webgl-gradient\" data-motion-palette=\"{{ settings.motion_palette }}\" data-motion-speed=\"{{ settings.motion_speed }}\" data-motion-intensity=\"{{ settings.motion_intensity }}\" data-motion-grain=\"{{ settings.motion_grain }}\">\n  <div class=\"gm__in\">\n    <h2 class=\"gm__h\">{{ settings.heading }}</h2>\n    {% if settings.text %}<p class=\"gm__text\">{{ settings.text }}</p>{% endif %}\n  </div>\n  {% if section.blocks.size > 0 %}\n  <div class=\"gm__run\" aria-label=\"{{ settings.run_label }}\" data-storelib-motion=\"marquee\" data-motion-speed=\"{{ settings.marquee_speed }}\" data-motion-reactive=\"{{ settings.marquee_reactive }}\" data-motion-direction=\"left\" data-motion-flip=\"true\" data-motion-pause=\"true\">\n    <ul class=\"gm__track\" data-motion-track>\n      {% for block in section.blocks %}<li class=\"gm__item\" data-block-id=\"{{ block.id }}\">{{ block.settings.text }}</li>{% endfor %}\n    </ul>\n  </div>\n  {% endif %}\n</section>\n</template>\n\n<style scoped>\n.gm { position: relative; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) 0 calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); overflow: hidden; }\n.gm__in { position: relative; max-width: var(--theme-page-width, 1280px); margin: 0 auto; padding-inline: var(--theme-padding-x, 16px); }\n.gm__h { margin: 0; max-width: 16ch; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2.25rem, 1.3rem + 4.4vw, 6rem); line-height: 0.95; letter-spacing: -0.035em; color: var(--s-heading); }\n.gm__text { max-width: 44ch; margin: 20px 0 0; font-size: 1.0625rem; line-height: 1.55; }\n.gm__run { position: relative; margin-top: clamp(40px, 8vw, 96px); overflow: hidden; }\n.gm__track { display: flex; flex-wrap: wrap; gap: 0 0.6em; margin: 0; padding: 0 var(--theme-padding-x, 16px); list-style: none; }\n.gm__item { font-family: var(--theme-font-heading), sans-serif; font-size: clamp(3rem, 1.5rem + 9vw, 11rem); line-height: 1; letter-spacing: -0.04em; white-space: nowrap; }\n.gm__item::after { content: \"*\"; margin-left: 0.3em; color: var(--s-accent); }\n/* Running: one row. Still (reduced motion, no runtime): the words wrap, all of them readable. */\n.gm__run[data-motion-ready] .gm__track { flex-wrap: nowrap; gap: 0; padding: 0; }\n.gm__run[data-motion-ready] .gm__item { padding-right: 0.6em; }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_gradient_marquee\",\n  \"name\": \"Gradient band with running line\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Ship the build, not the busywork\" },\n    { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"Deploy previews for every branch, logs you can read, and a rollback that takes one click.\" },\n    { \"type\": \"text\", \"id\": \"run_label\", \"label\": \"What the running line lists (read aloud)\", \"default\": \"Teams building on it\" },\n    { \"type\": \"text\", \"id\": \"motion_palette\", \"label\": \"Gradient colours\", \"default\": \"scheme\", \"info\": \"scheme, accent, mono or up to five #hex colours\" },\n    { \"type\": \"range\", \"id\": \"motion_speed\", \"label\": \"Gradient speed\", \"min\": 0, \"max\": 2, \"step\": 0.1, \"unit\": \"x\", \"default\": 0.4 },\n    { \"type\": \"range\", \"id\": \"motion_intensity\", \"label\": \"Flow\", \"min\": 0, \"max\": 100, \"step\": 5, \"unit\": \"%\", \"default\": 60 },\n    { \"type\": \"range\", \"id\": \"motion_grain\", \"label\": \"Grain\", \"min\": 0, \"max\": 100, \"step\": 5, \"unit\": \"%\", \"default\": 12 },\n    { \"type\": \"range\", \"id\": \"marquee_speed\", \"label\": \"Line speed\", \"min\": 10, \"max\": 400, \"step\": 10, \"unit\": \"px/s\", \"default\": 90 },\n    { \"type\": \"range\", \"id\": \"marquee_reactive\", \"label\": \"Scroll boost\", \"min\": 0, \"max\": 100, \"step\": 5, \"unit\": \"%\", \"default\": 50 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 120 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 64 }\n  ],\n  \"blocks\": [\n    { \"type\": \"word\", \"name\": \"Word\", \"settings\": [ { \"type\": \"text\", \"id\": \"text\", \"label\": \"Words\", \"default\": \"Northwind\" } ] }\n  ],\n  \"presets\": [{ \"name\": \"Gradient band with running line\", \"blocks\": [{ \"type\": \"word\", \"settings\": { \"text\": \"Northwind\" } }, { \"type\": \"word\", \"settings\": { \"text\": \"Halden Labs\" } }, { \"type\": \"word\", \"settings\": { \"text\": \"Fieldnote\" } }, { \"type\": \"word\", \"settings\": { \"text\": \"Oakbridge\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_hover_lift.storelib",
  "source": "{# example\ntitle: Hover lift and press\nsummary: An index of offers or programmes whose rows answer the pointer: the picture lifts and pans inside its crop, the arrow travels, and a press settles the row, all timed by the site's motion feel (--t-motion-hover, --t-motion-lift); touch keeps the press only, reduced motion keeps colour and underline feedback without movement.\ntags: hover, hover lift, press, tactile, micro interaction, card hover, image pan, offers, programmes, index, links, motion tier\n#}\n<template>\n<section class=\"hl\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px; --m-k: calc({{ settings.motion_strength }} / 100);\">\n  <div class=\"hl__in\">\n    {% if settings.heading %}<h2 class=\"hl__h\">{{ settings.heading }}</h2>{% endif %}\n    <ul class=\"hl__list\">\n      {% for block in section.blocks %}\n      <li class=\"hl__row\" data-block-id=\"{{ block.id }}\">\n        <a class=\"hl__link\" href=\"{{ block.settings.url | url }}\">\n          <span class=\"hl__body\">\n            <span class=\"hl__title\">{{ block.settings.title }}</span>\n            {% if block.settings.text %}<span class=\"hl__text\">{{ block.settings.text }}</span>{% endif %}\n          </span>\n          {% if block.settings.meta %}<span class=\"hl__meta\">{{ block.settings.meta }}</span>{% endif %}\n          <span class=\"hl__arrow\" aria-hidden=\"true\">&rarr;</span>\n          {% if block.settings.image %}<span class=\"hl__crop\"><img class=\"hl__img\" src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"800\" height=\"1000\" loading=\"lazy\"></span>{% endif %}\n        </a>\n      </li>\n      {% else %}\n      {% if page.in_editor %}<li class=\"hl__row hl__empty\">Add offers in the sidebar</li>{% endif %}\n      {% endfor %}\n    </ul>\n  </div>\n</section>\n</template>\n\n<style scoped>\n.hl { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.hl__in { max-width: var(--theme-page-width, 1280px); margin: 0 auto; }\n.hl__h { margin: 0 0 clamp(24px, 4vw, 48px); font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.9rem, 1.2rem + 2.8vw, 3.8rem); line-height: 1; letter-spacing: -0.03em; font-weight: 700; color: var(--s-heading); }\n.hl__list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--s-border); }\n.hl__row { border-bottom: 1px solid var(--s-border); }\n.hl__link { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px 20px; align-items: center; padding: 22px 0; min-height: 44px; color: inherit; text-decoration: none; }\n.hl__body { display: grid; gap: 6px; }\n.hl__title { font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.35rem, 1rem + 1.6vw, 2.3rem); line-height: 1.05; letter-spacing: -0.02em; font-weight: 700; color: var(--s-heading); text-decoration: underline; text-decoration-color: transparent; text-underline-offset: 6px; transition: text-decoration-color var(--t-motion-hover, 200ms) ease; }\n.hl__text { max-width: 54ch; font-size: 1rem; line-height: 1.55; }\n.hl__meta { font-size: 0.9375rem; font-variant-numeric: tabular-nums; white-space: nowrap; }\n.hl__arrow { display: none; }\n.hl__crop { grid-column: 1 / -1; display: block; overflow: hidden; aspect-ratio: 16 / 10; }\n.hl__img { display: block; width: 100%; height: 100%; object-fit: cover; }\n.hl__link:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 4px; }\n.hl__link:hover .hl__title, .hl__link:focus-visible .hl__title { text-decoration-color: currentColor; }\n.hl__empty { padding: 24px 0; opacity: 0.7; }\n@container (min-width: 760px) {\n  .hl__link { grid-template-columns: minmax(0, 1fr) auto 32px 168px; padding: 26px 0; }\n  .hl__body { grid-column: 1; grid-row: 1; }\n  .hl__meta { grid-column: 2; grid-row: 1; }\n  .hl__arrow { display: block; grid-column: 3; grid-row: 1; font-size: 1.5rem; color: var(--s-accent); }\n  .hl__crop { grid-column: 4; grid-row: 1; aspect-ratio: 4 / 5; }\n}\n/* Movement only when welcome. The press works on touch too; the lift and pan only on a pointer that hovers. */\n@media (prefers-reduced-motion: no-preference) {\n  .hl:not([data-motion=\"off\"]) .hl__link { transition: transform var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, cubic-bezier(0.3, 0.7, 0.4, 1)); }\n  .hl:not([data-motion=\"off\"]) .hl__link:active { transform: scale(0.985); }\n  .hl:not([data-motion=\"off\"]) .hl__img, .hl:not([data-motion=\"off\"]) .hl__crop, .hl:not([data-motion=\"off\"]) .hl__arrow { transition: transform calc(var(--t-motion-hover, 200ms) * 1.6) var(--t-motion-ease-ui, cubic-bezier(0.3, 0.7, 0.4, 1)); }\n  @media (hover: hover) and (pointer: fine) {\n    .hl:not([data-motion=\"off\"]) .hl__link:hover .hl__crop { transform: translateY(calc(var(--t-motion-lift, 4px) * -1 * var(--m-k, 1))); }\n    .hl:not([data-motion=\"off\"]) .hl__link:hover .hl__img { transform: scale(calc(1 + (var(--t-motion-scale, 1.06) - 1) * var(--m-k, 1))); }\n    .hl:not([data-motion=\"off\"]) .hl__link:hover .hl__arrow { transform: translateX(calc(var(--t-motion-lift, 4px) * 2 * var(--m-k, 1))); }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_hover_lift\",\n  \"name\": \"Offers that answer the pointer\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Ways to train\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 }\n  ],\n  \"blocks\": [\n    { \"type\": \"offer\", \"name\": \"Offer\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"One to one\" },\n      { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"Twelve sessions in the studio, a plan between them.\" },\n      { \"type\": \"text\", \"id\": \"meta\", \"label\": \"Detail on the right\", \"default\": \"\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Link\", \"default\": \"/about\" },\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Picture description\", \"default\": \"\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Offers that answer the pointer\", \"blocks\": [{ \"type\": \"offer\", \"settings\": { \"title\": \"One to one\", \"text\": \"Twelve sessions in the studio, a plan between them.\" } }, { \"type\": \"offer\", \"settings\": { \"title\": \"Small group\", \"text\": \"Four people, one coach, Tuesday and Thursday at 6.\" } }, { \"type\": \"offer\", \"settings\": { \"title\": \"Remote coaching\", \"text\": \"Your gym, a written plan, a video check in every Friday.\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_hover_reveal_list.storelib",
  "source": "{# example\ntitle: Index with hover image reveal\nsummary: A large text index of projects, artists or collections where the row you point at or focus shows its image, with :hover and :focus-within only; on phones each row shows a small thumbnail instead.\ntags: hover reveal, image reveal, index, project list, list, portfolio, artists, collections, :has\n#}\n<template>\n<section class=\"ix\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <h2 class=\"ix__h\">{{ settings.heading }}</h2>\n  <ul class=\"ix__list\">\n    {% for block in section.blocks %}\n      <li class=\"ix__row\" data-block-id=\"{{ block.id }}\">\n        <a class=\"ix__link\" href=\"{{ block.settings.url | url }}\">\n          <span class=\"ix__name\">{{ block.settings.name }}</span>\n          {% if block.settings.meta %}<span class=\"ix__meta\">{{ block.settings.meta }}</span>{% endif %}\n          {% if block.settings.image %}<img class=\"ix__img\" src=\"{{ block.settings.image | asset }}\" alt=\"\" width=\"640\" height=\"800\" loading=\"lazy\">{% endif %}\n        </a>\n      </li>\n    {% else %}\n      {% if page.in_editor %}<li class=\"ix__empty\">Add rows in the sidebar</li>{% endif %}\n    {% endfor %}\n  </ul>\n</section>\n</template>\n\n<style scoped>\n.ix { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.ix__h { margin: 0 0 24px; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2.25rem); font-weight: 600; letter-spacing: -0.01em; line-height: 1.1; color: var(--s-heading, var(--s-text)); }\n.ix__list { position: relative; list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--s-border); }\n.ix__row { border-bottom: 1px solid var(--s-border); }\n.ix__link { display: grid; grid-template-columns: minmax(0, 1fr) 64px; align-items: center; gap: 4px 16px; padding: 18px 0; color: inherit; text-decoration: none; }\n.ix__name { font-family: var(--theme-font-heading), serif; font-size: clamp(1.75rem, 1rem + 4vw, 5rem); line-height: 1; letter-spacing: -0.03em; font-weight: 500; color: var(--s-heading); transition: color var(--t-motion-hover, 160ms) ease, transform var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, ease); }\n.ix__meta { grid-row: 2; font-size: 0.875rem; letter-spacing: 0.06em; }\n.ix__img { grid-row: 1 / span 2; grid-column: 2; width: 64px; height: 80px; object-fit: cover; }\n.ix__link:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 4px; }\n.ix__empty { padding: 24px 0; opacity: 0.7; }\n/* On a pointer that hovers, the picture leaves the row and floats beside the list. */\n@media (hover: hover) and (pointer: fine) {\n  @container (min-width: 820px) {\n    .ix__link { grid-template-columns: minmax(0, 1fr) auto; }\n    .ix__meta { grid-row: auto; }\n    .ix__img { position: absolute; right: 0; top: 50%; width: min(32%, 360px); height: auto; aspect-ratio: 4 / 5; opacity: 0; transform: translateY(-50%) scale(0.96); pointer-events: none; transition: opacity var(--t-motion-hover, 200ms) ease, transform calc(var(--t-motion-hover, 200ms) * 1.3) var(--t-motion-ease-ui, ease); }\n    .ix__row:hover .ix__img, .ix__row:focus-within .ix__img { opacity: 1; transform: translateY(-50%) scale(1); }\n    .ix__list:has(.ix__row:hover) .ix__name { color: color-mix(in srgb, var(--s-heading) 35%, transparent); }\n    .ix__list .ix__row:hover .ix__name, .ix__row:focus-within .ix__name { color: var(--s-heading); transform: translateX(12px); }\n  }\n}\n@media (prefers-reduced-motion: reduce) { .ix__img, .ix__name { transition: none; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_hover_reveal_list\",\n  \"name\": \"Index with pictures\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Selected work\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 64 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 }\n  ],\n  \"blocks\": [\n    { \"type\": \"row\", \"name\": \"Row\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"name\", \"label\": \"Name\", \"default\": \"Harbour House\" },\n      { \"type\": \"text\", \"id\": \"meta\", \"label\": \"Details\", \"default\": \"Residential, 2025\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Link\", \"default\": \"/about\" },\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Index with pictures\", \"blocks\": [{ \"type\": \"row\", \"settings\": { \"name\": \"Harbour House\", \"meta\": \"Residential, 2025\" } }, { \"type\": \"row\", \"settings\": { \"name\": \"Mill Lane Studio\", \"meta\": \"Workplace, 2024\" } }, { \"type\": \"row\", \"settings\": { \"name\": \"The Granary\", \"meta\": \"Conversion, 2023\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_hscroll_gallery.storelib",
  "source": "{# example\ntitle: Horizontal scroll gallery\nsummary: A row of images that scrolls sideways with snap points, keyboard scrollable (the track takes focus, arrow keys move it), a progress line tied to the scroll with CSS, captions under each picture.\ntags: horizontal scroll, gallery, carousel, slider, scroll-snap, process, crate, images, scroll-timeline\n#}\n<template>\n<section class=\"hg\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <div class=\"hg__head\">\n    <h2 class=\"hg__h\">{{ settings.heading }}</h2>\n    {% if settings.hint %}<p class=\"hg__hint\">{{ settings.hint }}</p>{% endif %}\n  </div>\n  <div class=\"hg__track\" tabindex=\"0\" role=\"region\" aria-label=\"{{ settings.heading }}\">\n    {% for block in section.blocks %}\n      <figure class=\"hg__item\" data-block-id=\"{{ block.id }}\">\n        {% if block.settings.image %}<img class=\"hg__img\" src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"900\" height=\"1125\" loading=\"lazy\">{% elsif page.in_editor %}<div class=\"hg__ph\">Add a photo</div>{% endif %}\n        {% if block.settings.caption %}<figcaption class=\"hg__cap\">{{ block.settings.caption }}</figcaption>{% endif %}\n      </figure>\n    {% else %}\n      {% if page.in_editor %}<p class=\"hg__empty\">Add pictures in the sidebar</p>{% endif %}\n    {% endfor %}\n  </div>\n  <div class=\"hg__bar\" aria-hidden=\"true\"><span class=\"hg__fill\"></span></div>\n</section>\n</template>\n\n<style scoped>\n.hg { timeline-scope: --hg; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) 0 calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.hg__head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 8px 24px; padding-inline: var(--theme-padding-x, 16px); margin-bottom: 24px; }\n.hg__h { margin: 0; font-family: var(--theme-font-heading), serif; font-size: clamp(1.75rem, 1.2rem + 2.4vw, 3.25rem); line-height: 1; letter-spacing: -0.02em; font-weight: 500; color: var(--s-heading); }\n.hg__hint { margin: 0; font-size: 0.9375rem; }\n.hg__track { display: grid; grid-auto-flow: column; grid-auto-columns: min(78%, 420px); gap: 12px; overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x mandatory; scroll-padding-inline: var(--theme-padding-x, 16px); padding-inline: var(--theme-padding-x, 16px); scrollbar-width: none; scroll-timeline: --hg inline; }\n.hg__track::-webkit-scrollbar { display: none; }\n.hg__track:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 4px; }\n.hg__item { margin: 0; scroll-snap-align: start; }\n.hg__img, .hg__ph { display: block; width: 100%; height: auto; aspect-ratio: 4 / 5; object-fit: cover; }\n.hg__ph { display: grid; place-items: center; border: 1px dashed var(--s-border); }\n.hg__cap { margin-top: 10px; font-size: 0.875rem; line-height: 1.45; }\n.hg__empty { opacity: 0.7; }\n.hg__bar { height: 2px; margin: 24px var(--theme-padding-x, 16px) 0; background: var(--s-border); overflow: hidden; }\n.hg__fill { display: block; height: 100%; background: var(--s-accent); transform-origin: left; transform: scaleX(0.15); }\n@supports (animation-timeline: scroll()) {\n  .hg__fill { animation: hg-fill linear both; animation-timeline: --hg; }\n  @keyframes hg-fill { from { transform: scaleX(0.05); } to { transform: scaleX(1); } }\n}\n@media (prefers-reduced-motion: reduce) { .hg__track { scroll-snap-type: none; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_hscroll_gallery\",\n  \"name\": \"Sideways gallery\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"From clay to kiln\" },\n    { \"type\": \"text\", \"id\": \"hint\", \"label\": \"Hint\", \"default\": \"Scroll sideways\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 80 }\n  ],\n  \"blocks\": [\n    { \"type\": \"picture\", \"name\": \"Picture\", \"settings\": [\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" },\n      { \"type\": \"text\", \"id\": \"caption\", \"label\": \"Caption\", \"default\": \"\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Sideways gallery\", \"blocks\": [{ \"type\": \"picture\", \"settings\": { \"caption\": \"Wedging\" } }, { \"type\": \"picture\", \"settings\": { \"caption\": \"Throwing\" } }, { \"type\": \"picture\", \"settings\": { \"caption\": \"Glazing\" } }, { \"type\": \"picture\", \"settings\": { \"caption\": \"Firing\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_image_reveal.storelib",
  "source": "{# example\ntitle: Image curtain and scale-in\nsummary: One key photograph that opens like a curtain and settles from a slight scale as it scrolls into view, on a CSS view timeline (clip-path and transform only), sized by the site's motion feel; strength and curtain direction are editable, phones get the scale only, reduced motion gets the still photo.\ntags: image reveal, curtain, scale in, scale reveal, clip-path, photo, cinematic, scroll, view-timeline, motion tier, image curtain\n#}\n<template>\n<section class=\"ir ir--{{ settings.width }}\" data-motion=\"{{ settings.motion }}\" data-curtain=\"{{ settings.curtain }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px; --m-k: calc({{ settings.motion_strength }} / 100); --ir-ratio: {{ settings.ratio }};\">\n  <figure class=\"ir__fig\">\n    <div class=\"ir__frame\">\n      {% if settings.image %}<img class=\"ir__img\" src=\"{{ settings.image | asset }}\" alt=\"{{ settings.image_alt }}\" width=\"2400\" height=\"1600\" loading=\"lazy\">{% elsif page.in_editor %}<p class=\"ir__ph\">Pick the photo this section is for in the sidebar</p>{% endif %}\n    </div>\n    {% if settings.caption %}<figcaption class=\"ir__cap\">{{ settings.caption }}</figcaption>{% endif %}\n  </figure>\n</section>\n</template>\n\n<style scoped>\n.ir { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) 0 calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.ir--inset .ir__fig { max-width: min(var(--theme-page-width, 1280px), 100%); padding-inline: var(--theme-padding-x, 16px); }\n.ir__fig { margin: 0 auto; }\n.ir__frame { position: relative; overflow: hidden; aspect-ratio: var(--ir-ratio, 16 / 9); background: color-mix(in srgb, var(--s-text) 8%, var(--s-bg)); }\n.ir__img { display: block; width: 100%; height: 100%; object-fit: cover; }\n.ir__ph { display: grid; place-items: center; height: 100%; margin: 0; padding: 16px; text-align: center; opacity: 0.7; }\n.ir__cap { display: flex; justify-content: space-between; gap: 16px; padding: 12px var(--theme-padding-x, 16px) 0; font-size: 0.875rem; line-height: 1.45; }\n.ir--inset .ir__cap { padding-inline: 0; }\n/* The whole photo is the default. The curtain and the settle only run where the browser ties them to scroll and motion is welcome. */\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .ir:not([data-motion=\"off\"]) .ir__img { animation: ir-settle linear both; animation-timeline: view(); animation-range: entry 0% cover 45%; }\n    /* A phone gets the settle only: a curtain across a narrow photo hides its subject. */\n    @container (min-width: 601px) {\n      .ir:not([data-motion=\"off\"])[data-curtain=\"up\"] .ir__frame { animation: ir-up linear both; animation-timeline: view(); animation-range: entry 0% entry 90%; }\n      .ir:not([data-motion=\"off\"])[data-curtain=\"side\"] .ir__frame { animation: ir-side linear both; animation-timeline: view(); animation-range: entry 0% entry 90%; }\n    }\n    @keyframes ir-settle { from { transform: scale(calc(1 + (var(--t-motion-scale, 1.06) - 1) * var(--m-k, 1))); } to { transform: scale(1); } }\n    @keyframes ir-up { from { clip-path: inset(calc(28% * var(--m-k, 1)) 0 0 0); } to { clip-path: inset(0); } }\n    @keyframes ir-side { from { clip-path: inset(0 calc(18% * var(--m-k, 1))); } to { clip-path: inset(0); } }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_image_reveal\",\n  \"name\": \"Photo that opens\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n    { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" },\n    { \"type\": \"text\", \"id\": \"caption\", \"label\": \"Caption\", \"default\": \"\" },\n    { \"type\": \"select\", \"id\": \"width\", \"label\": \"Width\", \"default\": \"full\", \"options\": [{ \"label\": \"Edge to edge\", \"value\": \"full\" }, { \"label\": \"Inside the page\", \"value\": \"inset\" }] },\n    { \"type\": \"select\", \"id\": \"ratio\", \"label\": \"Shape\", \"default\": \"16 / 9\", \"options\": [{ \"label\": \"Wide\", \"value\": \"16 / 9\" }, { \"label\": \"Cinema\", \"value\": \"21 / 9\" }, { \"label\": \"Classic\", \"value\": \"3 / 2\" }, { \"label\": \"Tall\", \"value\": \"4 / 5\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"select\", \"id\": \"curtain\", \"label\": \"Opens\", \"default\": \"up\", \"options\": [{ \"label\": \"From below\", \"value\": \"up\" }, { \"label\": \"From the sides\", \"value\": \"side\" }, { \"label\": \"No curtain, settle only\", \"value\": \"none\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 48 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 48 }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_image_trail.storelib",
  "source": "{# example\ntitle: Project index with an image trail and a cursor label (motion islands)\nsummary: A big typographic index of projects; moving the mouse across the section leaves a trail of the projects' photos that fade behind it (the image-trail motion island) and a round View label follows the pointer over the list (cursor-follow); on touch and with reduced motion the photos are a plain still row and every project is a link.\ntags: image trail, mouse trail, cursor follow, cursor label, portfolio, project index, playful, photographer, studio, creative, motion islands, hover\n#}\n<template>\n<section class=\"it\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn-text: {{ scheme.primary_btn_text }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\" data-storelib-motion=\"image-trail\" data-motion-threshold=\"{{ settings.motion_threshold }}\" data-motion-lifetime=\"{{ settings.motion_lifetime }}\" data-motion-max=\"{{ settings.motion_max }}\" data-motion-size=\"{{ settings.motion_size }}\" data-motion-rotate=\"{{ settings.motion_rotate }}\">\n  <h2 class=\"it__h\">{{ settings.heading }}</h2>\n  <div class=\"it__index\" data-storelib-motion=\"cursor-follow\" data-motion-label=\"{{ settings.cursor_label }}\" data-motion-size=\"80\">\n  <ol class=\"it__list\">\n    {% for block in section.blocks %}\n    <li class=\"it__row\" data-block-id=\"{{ block.id }}\">\n      {% if block.settings.url %}<a class=\"it__link\" href=\"{{ block.settings.url | url }}\">{{ block.settings.title }}</a>{% else %}<span class=\"it__link\">{{ block.settings.title }}</span>{% endif %}\n      <span class=\"it__meta\">{{ block.settings.meta }}</span>\n    </li>\n    {% endfor %}\n  </ol>\n  </div>\n  <ul class=\"it__pics\" data-motion-images>\n    {% for block in section.blocks %}{% if block.settings.image %}<li><img class=\"it__pic\" src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"600\" height=\"450\" loading=\"lazy\"></li>{% endif %}{% endfor %}\n  </ul>\n</section>\n</template>\n\n<style scoped>\n.it { min-height: 60svh; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); overflow: hidden; }\n.it__h { margin: 0 0 32px; font-size: 1rem; font-weight: 600; color: var(--s-heading); }\n.it__index { position: relative; z-index: 3; }\n.it__list { margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--s-border); }\n.it__row { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 4px 24px; padding: 14px 0; border-bottom: 1px solid var(--s-border); }\n.it__link { font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.75rem, 1rem + 3.6vw, 4.5rem); line-height: 1; letter-spacing: -0.03em; color: inherit; text-decoration: none; }\n.it__link:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 4px; }\n.it__meta { font-size: 0.9375rem; opacity: 0.75; }\n.it__pics { display: flex; gap: 10px; margin: 28px 0 0; padding: 0; list-style: none; overflow-x: auto; }\n.it__pic { display: block; width: 160px; height: auto; aspect-ratio: 4 / 3; object-fit: cover; }\n@media (prefers-reduced-motion: no-preference) and (hover: hover) and (pointer: fine) {\n  .it__link { transition: color var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, ease-out); }\n  .it__row:hover .it__link { color: var(--s-accent); }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_image_trail\",\n  \"name\": \"Project index with image trail\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Selected work, 2021 to now\" },\n    { \"type\": \"text\", \"id\": \"cursor_label\", \"label\": \"Cursor label\", \"default\": \"View\" },\n    { \"type\": \"range\", \"id\": \"motion_threshold\", \"label\": \"Spacing\", \"min\": 20, \"max\": 300, \"step\": 10, \"unit\": \"px\", \"default\": 80 },\n    { \"type\": \"range\", \"id\": \"motion_lifetime\", \"label\": \"Fade after\", \"min\": 200, \"max\": 2500, \"step\": 100, \"unit\": \"ms\", \"default\": 900 },\n    { \"type\": \"range\", \"id\": \"motion_max\", \"label\": \"Pictures at once\", \"min\": 2, \"max\": 16, \"step\": 1, \"default\": 7 },\n    { \"type\": \"range\", \"id\": \"motion_size\", \"label\": \"Picture size\", \"min\": 60, \"max\": 400, \"step\": 10, \"unit\": \"px\", \"default\": 200 },\n    { \"type\": \"range\", \"id\": \"motion_rotate\", \"label\": \"Tilt\", \"min\": 0, \"max\": 30, \"step\": 1, \"unit\": \"deg\", \"default\": 6 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 }\n  ],\n  \"blocks\": [\n    { \"type\": \"project\", \"name\": \"Project\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"Harbour lights\" },\n      { \"type\": \"text\", \"id\": \"meta\", \"label\": \"Client and year\", \"default\": \"Port authority, 2024\" },\n      { \"type\": \"url\", \"id\": \"url\", \"label\": \"Link\", \"default\": \"/work\" },\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Project index with image trail\", \"blocks\": [{ \"type\": \"project\", \"settings\": { \"title\": \"Harbour lights\", \"meta\": \"Port authority, 2024\", \"url\": \"/work\" } }, { \"type\": \"project\", \"settings\": { \"title\": \"Salt and iron\", \"meta\": \"Kettle and Co, 2023\", \"url\": \"/work\" } }, { \"type\": \"project\", \"settings\": { \"title\": \"Night bakery\", \"meta\": \"Crumb, 2023\", \"url\": \"/work\" } }, { \"type\": \"project\", \"settings\": { \"title\": \"North shore\", \"meta\": \"Coastal trust, 2022\", \"url\": \"/work\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_marquee.storelib",
  "source": "{# example\ntitle: Marquee of real words\nsummary: A slow running line of the creator's own words (dates, today's bakes, a release name), drawn twice so it loops seamlessly; pauses on hover and focus and with its own Pause switch (a checkbox and :has(), no script), stands still under reduced motion, and screen readers hear it once.\ntags: marquee, ticker, running text, loop, scrolling text, banner, motion, pause, marquee with pause\n#}\n<template>\n<section class=\"mq\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-accent: {{ scheme.accent }}; --mq-speed: {{ settings.speed }}s;\" aria-label=\"{{ settings.label }}\">\n  {% if section.blocks.size > 0 %}\n  <div class=\"mq__track\">\n    <ul class=\"mq__run\">\n      {% for block in section.blocks %}<li class=\"mq__item\" data-block-id=\"{{ block.id }}\">{{ block.settings.text }}</li>{% endfor %}\n    </ul>\n    <ul class=\"mq__run\" aria-hidden=\"true\">\n      {% for block in section.blocks %}<li class=\"mq__item\">{{ block.settings.text }}</li>{% endfor %}\n    </ul>\n  </div>\n  {% if settings.pause_label %}<label class=\"mq__pause\"><input class=\"mq__toggle\" type=\"checkbox\"><span>{{ settings.pause_label }}</span></label>{% endif %}\n  {% elsif page.in_editor %}\n  <p class=\"mq__empty\">Add lines in the sidebar</p>\n  {% endif %}\n</section>\n</template>\n\n<style scoped>\n.mq { position: relative; overflow: hidden; background: var(--s-bg); color: var(--s-text); border-block: 1px solid currentColor; }\n.mq__track { display: flex; width: max-content; }\n.mq__run { display: flex; flex: none; margin: 0; padding: 0; list-style: none; }\n.mq__item { padding: 14px 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.25rem, 0.9rem + 1.6vw, 2.25rem); line-height: 1; letter-spacing: -0.01em; text-transform: uppercase; white-space: nowrap; }\n.mq__item::after { content: \"/\"; margin-inline: 0.6em; color: var(--s-accent); }\n.mq__pause { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); display: none; align-items: center; gap: 6px; min-height: 44px; padding: 0 12px; background: var(--s-bg); color: var(--s-text); font-size: 0.8125rem; cursor: pointer; }\n.mq__toggle { width: 16px; height: 16px; margin: 0; accent-color: var(--s-accent); }\n.mq__pause:focus-within { outline: 2px solid var(--s-accent); outline-offset: -2px; }\n.mq__empty { margin: 0; padding: 16px; opacity: 0.7; }\n/* Without motion it is a line that wraps, so every word is still there. */\n@media (prefers-reduced-motion: reduce) {\n  .mq__track { width: auto; }\n  .mq__run { flex-wrap: wrap; padding-inline: 16px; }\n  .mq__run[aria-hidden=\"true\"] { display: none; }\n}\n@media (prefers-reduced-motion: no-preference) {\n  .mq__track { animation: mq-run var(--mq-speed, 40s) linear infinite; }\n  .mq:hover .mq__track, .mq:focus-within .mq__track, .mq:has(.mq__toggle:checked) .mq__track { animation-play-state: paused; }\n  .mq__pause { display: inline-flex; }\n  @keyframes mq-run { to { transform: translateX(-50%); } }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_marquee\",\n  \"name\": \"Running line\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"What it lists (read aloud)\", \"default\": \"Coming up\" },\n    { \"type\": \"text\", \"id\": \"pause_label\", \"label\": \"Pause switch (empty hides it)\", \"default\": \"Pause\" },\n    { \"type\": \"range\", \"id\": \"speed\", \"label\": \"Seconds per loop\", \"min\": 15, \"max\": 90, \"step\": 5, \"unit\": \"s\", \"default\": 40 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"line\", \"name\": \"Line\", \"settings\": [ { \"type\": \"text\", \"id\": \"text\", \"label\": \"Words\", \"default\": \"Friday 14 March, Leeds\" } ] }\n  ],\n  \"presets\": [{ \"name\": \"Running line\", \"blocks\": [{ \"type\": \"line\", \"settings\": { \"text\": \"Friday 14 March, Leeds\" } }, { \"type\": \"line\", \"settings\": { \"text\": \"Saturday 15 March, Glasgow\" } }, { \"type\": \"line\", \"settings\": { \"text\": \"Sunday 16 March, Belfast\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_mask_reveal.storelib",
  "source": "{# example\ntitle: Masked line reveal\nsummary: An opening statement whose lines rise out of clipped masks one after another, timed by the site's motion feel (--t-motion-*) with stagger and strength the creator edits; one real heading for screen readers, still under reduced motion, shorter travel on phones.\ntags: masked reveal, mask reveal, line reveal, text reveal, headline, hero, statement, stagger, motion, motion tier, opening\n#}\n<template>\n<section class=\"mr\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-btn-bg: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px; --m-k: calc({{ settings.motion_strength }} / 100); --mr-stagger: {{ settings.stagger }}ms;\">\n  <div class=\"mr__in mr__in--{{ settings.align }}\">\n    <h1 class=\"mr__h\">\n      {% for block in section.blocks %}<span class=\"mr__line\" data-block-id=\"{{ block.id }}\" style=\"--i: {{ forloop.index0 }};\"><span class=\"mr__words{% if block.settings.weight == 'light' %} mr__words--light{% endif %}\">{{ block.settings.line }}</span></span>{% endfor %}\n    </h1>\n    {% if settings.text %}<p class=\"mr__text\">{{ settings.text }}</p>{% endif %}\n    {% if settings.cta_label and settings.cta_url %}<a class=\"mr__cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}\n  </div>\n</section>\n</template>\n\n<style scoped>\n.mr { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.mr__in { max-width: var(--theme-page-width, 1280px); margin: 0 auto; display: grid; gap: clamp(20px, 3vw, 36px); }\n.mr__in--right { justify-items: end; text-align: right; }\n.mr__h { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2.6rem, 1rem + 7.2vw, 8.5rem); line-height: 0.92; letter-spacing: -0.035em; font-weight: 700; color: var(--s-heading); text-wrap: balance; }\n.mr__line { display: block; overflow: hidden; padding-bottom: 0.08em; margin-bottom: -0.08em; }\n.mr__words { display: inline-block; }\n.mr__words--light { font-weight: 400; color: color-mix(in srgb, var(--s-heading) 62%, var(--s-bg)); }\n.mr__text { margin: 0; max-width: 46ch; font-size: clamp(1.05rem, 0.95rem + 0.4vw, 1.25rem); line-height: 1.55; }\n.mr__cta { justify-self: start; display: inline-flex; align-items: center; min-height: 48px; padding: 0 24px; background: var(--s-btn-bg); color: var(--s-btn-text); text-decoration: none; font-weight: 600; border-radius: var(--t-radius-sm, 2px); transition: transform var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, ease-out); }\n.mr__in--right .mr__cta { justify-self: end; }\n.mr__cta:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n.mr__cta:active { transform: scale(0.98); }\n/* The still headline is the default. Motion only when welcome, and never when the creator set this section to still. */\n@media (prefers-reduced-motion: no-preference) {\n  .mr:not([data-motion=\"off\"]) .mr__words { animation: mr-rise var(--t-motion-duration, 650ms) var(--t-motion-ease, cubic-bezier(0.2, 0.7, 0.2, 1)) both; animation-delay: calc(var(--i) * var(--mr-stagger, 70ms) * var(--m-phone, 1) + 80ms); }\n  .mr:not([data-motion=\"off\"]) .mr__text, .mr:not([data-motion=\"off\"]) .mr__cta { animation: mr-fade var(--t-motion-duration, 650ms) var(--t-motion-ease, ease-out) both; animation-delay: calc(4 * var(--mr-stagger, 70ms) + 160ms); }\n  @keyframes mr-rise { from { transform: translateY(calc(108% * var(--m-k, 1) * var(--m-phone, 1))); } to { transform: none; } }\n  @keyframes mr-fade { from { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 0.5 * var(--m-k, 1))); } to { opacity: 1; transform: none; } }\n}\n/* On a phone the lines travel less and follow each other faster. */\n@container (max-width: 600px) {\n  .mr__in { --m-phone: 0.65; }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_mask_reveal\",\n  \"name\": \"Masked headline\",\n  \"category\": \"hero\",\n  \"settings\": [\n    { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text under the headline\", \"default\": \"Strength sessions in a small room in Salford, built around the hours you actually have.\" },\n    { \"type\": \"text\", \"id\": \"cta_label\", \"label\": \"Button\", \"default\": \"Book a first session\" },\n    { \"type\": \"url\", \"id\": \"cta_url\", \"label\": \"Button link\", \"default\": \"/about\" },\n    { \"type\": \"select\", \"id\": \"align\", \"label\": \"Alignment\", \"default\": \"left\", \"options\": [{ \"label\": \"Left\", \"value\": \"left\" }, { \"label\": \"Right\", \"value\": \"right\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"range\", \"id\": \"stagger\", \"label\": \"Delay between lines\", \"min\": 0, \"max\": 150, \"step\": 5, \"unit\": \"ms\", \"default\": 70 },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 240, \"step\": 8, \"unit\": \"px\", \"default\": 120 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 240, \"step\": 8, \"unit\": \"px\", \"default\": 88 }\n  ],\n  \"blocks\": [\n    { \"type\": \"line\", \"name\": \"Line\", \"limit\": 5, \"settings\": [\n      { \"type\": \"text\", \"id\": \"line\", \"label\": \"Words on this line\", \"default\": \"Train with\" },\n      { \"type\": \"select\", \"id\": \"weight\", \"label\": \"Weight\", \"default\": \"bold\", \"options\": [{ \"label\": \"Bold\", \"value\": \"bold\" }, { \"label\": \"Light\", \"value\": \"light\" }] }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Masked headline\", \"blocks\": [{ \"type\": \"line\", \"settings\": { \"line\": \"Stronger in\" } }, { \"type\": \"line\", \"settings\": { \"line\": \"three hours\", \"weight\": \"light\" } }, { \"type\": \"line\", \"settings\": { \"line\": \"a week.\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_object_hero.storelib",
  "source": "{# example\ntitle: 3D product hero (motion islands)\nsummary: A launch hero whose product photo sits on a real lit 3D card that turns with the scroll and leans toward the pointer (the 3d-object motion island, three.js loaded only on this page), with a decoding label (text-scramble); every motion param is a sidebar setting, and the photo itself is the still state for reduced motion, phones without WebGL and low-power devices.\ntags: 3d, 3d object, three.js, webgl, product hero, launch, rotating product, rotate on scroll, tilt, motion islands, text scramble, awwwards, immersive, watch, drink, app\n#}\n<template>\n<section class=\"oh\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-btn-bg: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px; --oh-h: {{ settings.object_height }}px;\">\n  <div class=\"oh__in\">\n    <div class=\"oh__copy\">\n      {% if settings.label %}<p class=\"oh__label\" data-storelib-motion=\"text-scramble\" data-motion-trigger=\"load\" data-motion-chars=\"symbols\" data-motion-duration=\"1100\">{{ settings.label }}</p>{% endif %}\n      <h1 class=\"oh__h\">{{ settings.heading }}</h1>\n      {% if settings.text %}<p class=\"oh__text\">{{ settings.text }}</p>{% endif %}\n      {% if settings.cta_label and settings.cta_url %}<a class=\"oh__cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}\n    </div>\n    <div class=\"oh__stage\" data-storelib-motion=\"3d-object\" data-motion-shape=\"{{ settings.motion_shape }}\" data-motion-rotate=\"{{ settings.motion_rotate }}\" data-motion-speed=\"{{ settings.motion_speed }}\" data-motion-intensity=\"{{ settings.motion_intensity }}\" data-motion-finish=\"{{ settings.motion_finish }}\" data-motion-light=\"{{ settings.motion_light }}\" data-motion-color=\"{{ settings.motion_color }}\" data-motion-float=\"{{ settings.motion_float }}\">\n      {% if settings.image %}<img class=\"oh__img\" data-motion-fallback src=\"{{ settings.image | asset }}\" alt=\"{{ settings.image_alt }}\" width=\"900\" height=\"1200\">{% else %}<span class=\"oh__orb\" aria-hidden=\"true\"></span>{% endif %}\n    </div>\n  </div>\n</section>\n</template>\n\n<style scoped>\n.oh { padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); overflow: hidden; }\n.oh__in { display: grid; gap: 32px; max-width: var(--theme-page-width, 1280px); margin: 0 auto; align-items: center; }\n.oh__label { margin: 0 0 18px; font-family: var(--theme-font-body), sans-serif; font-size: 0.875rem; font-variant-numeric: tabular-nums; color: var(--s-accent); }\n.oh__h { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2.75rem, 1.6rem + 6vw, 7.5rem); line-height: 0.92; letter-spacing: -0.035em; font-weight: 700; color: var(--s-heading); text-wrap: balance; }\n.oh__text { max-width: 40ch; margin: 22px 0 0; font-size: 1.0625rem; line-height: 1.55; }\n.oh__cta { display: inline-flex; align-items: center; min-height: 48px; margin-top: 28px; padding: 0 22px; background: var(--s-btn-bg); color: var(--s-btn-text); text-decoration: none; font-weight: 600; border-radius: var(--theme-radius-button, 999px); transition: transform var(--t-motion-hover, 200ms) var(--t-motion-ease-ui, ease-out); }\n.oh__cta:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n.oh__stage { position: relative; height: min(var(--oh-h), 70svh); display: grid; place-items: center; }\n.oh__img { display: block; height: 100%; width: auto; max-width: 100%; object-fit: contain; }\n.oh__orb { width: min(60vw, 340px); aspect-ratio: 1; border-radius: 50%; background: radial-gradient(circle at 32% 28%, color-mix(in srgb, var(--s-accent) 35%, #fff), var(--s-accent) 55%, color-mix(in srgb, var(--s-accent) 60%, #000)); }\n@media (min-width: 900px) { .oh__in { grid-template-columns: 1.1fr 1fr; gap: 48px; } }\n@media (prefers-reduced-motion: no-preference) and (hover: hover) and (pointer: fine) { .oh__cta:hover { transform: translateY(calc(var(--t-motion-lift, 4px) * -1)); } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_object_hero\",\n  \"name\": \"3D product hero\",\n  \"category\": \"hero\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"Label\", \"default\": \"Series 02, out now\" },\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Built to be held\" },\n    { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"Machined from one piece of aluminium, finished by hand, made to last longer than the phone you keep in it.\" },\n    { \"type\": \"text\", \"id\": \"cta_label\", \"label\": \"Button\", \"default\": \"Shop the series\" },\n    { \"type\": \"url\", \"id\": \"cta_url\", \"label\": \"Button link\", \"default\": \"/shop\" },\n    { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Product photo\" },\n    { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" },\n    { \"type\": \"range\", \"id\": \"object_height\", \"label\": \"Object height\", \"min\": 320, \"max\": 800, \"step\": 20, \"unit\": \"px\", \"default\": 560 },\n    { \"type\": \"select\", \"id\": \"motion_shape\", \"label\": \"Shape\", \"options\": [{ \"value\": \"card\", \"label\": \"Card\" }, { \"value\": \"sphere\", \"label\": \"Sphere\" }, { \"value\": \"torus\", \"label\": \"Ring\" }, { \"value\": \"knot\", \"label\": \"Knot\" }, { \"value\": \"box\", \"label\": \"Box\" }, { \"value\": \"blob\", \"label\": \"Blob\" }, { \"value\": \"coin\", \"label\": \"Coin\" }], \"default\": \"card\" },\n    { \"type\": \"select\", \"id\": \"motion_rotate\", \"label\": \"Turns with\", \"options\": [{ \"value\": \"scroll\", \"label\": \"Scroll\" }, { \"value\": \"pointer\", \"label\": \"Pointer\" }, { \"value\": \"both\", \"label\": \"Scroll and pointer\" }, { \"value\": \"auto\", \"label\": \"On its own\" }], \"default\": \"both\" },\n    { \"type\": \"range\", \"id\": \"motion_speed\", \"label\": \"Speed\", \"min\": 0, \"max\": 2, \"step\": 0.1, \"unit\": \"x\", \"default\": 0.6 },\n    { \"type\": \"range\", \"id\": \"motion_intensity\", \"label\": \"Turn\", \"min\": 0, \"max\": 100, \"step\": 5, \"unit\": \"%\", \"default\": 50 },\n    { \"type\": \"select\", \"id\": \"motion_finish\", \"label\": \"Finish\", \"options\": [{ \"value\": \"matte\", \"label\": \"Matte\" }, { \"value\": \"satin\", \"label\": \"Satin\" }, { \"value\": \"gloss\", \"label\": \"Gloss\" }, { \"value\": \"metal\", \"label\": \"Metal\" }], \"default\": \"satin\" },\n    { \"type\": \"select\", \"id\": \"motion_light\", \"label\": \"Light\", \"options\": [{ \"value\": \"studio\", \"label\": \"Studio\" }, { \"value\": \"soft\", \"label\": \"Soft\" }, { \"value\": \"dramatic\", \"label\": \"Dramatic\" }], \"default\": \"studio\" },\n    { \"type\": \"text\", \"id\": \"motion_color\", \"label\": \"Shape colour\", \"default\": \"accent\", \"info\": \"accent, scheme, mono or a #hex colour\" },\n    { \"type\": \"checkbox\", \"id\": \"motion_float\", \"label\": \"Float\", \"default\": true },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 }\n  ],\n  \"presets\": [{ \"name\": \"3D product hero\" }]\n}\n</schema>\n"
 },
 {
  "file": "ai_parallax_media.storelib",
  "source": "{# example\ntitle: Parallax image band\nsummary: A full bleed photo that drifts slower than the page as it passes, with a CSS view timeline on a transform only; a still photo without support or with reduced motion, and the caption is always plain text.\ntags: parallax, full bleed, image band, scroll, depth, photo, view-timeline\n#}\n<template>\n<section class=\"px\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --px-h: {{ settings.height }}svh; --px-shift: {{ settings.strength }}%;\">\n  <div class=\"px__frame\">\n    {% if settings.image %}<img class=\"px__img\" src=\"{{ settings.image | asset }}\" alt=\"{{ settings.image_alt }}\" width=\"2400\" height=\"1600\" loading=\"lazy\">{% elsif page.in_editor %}<p class=\"px__ph\">Pick a wide photo in the sidebar</p>{% endif %}\n  </div>\n  {% if settings.caption %}<p class=\"px__cap\">{{ settings.caption }}</p>{% endif %}\n</section>\n</template>\n\n<style scoped>\n.px { background: var(--s-bg); color: var(--s-text); }\n.px__frame { position: relative; height: var(--px-h, 70svh); min-height: 280px; overflow: hidden; }\n.px__img { position: absolute; inset: -12% 0; width: 100%; height: 124%; object-fit: cover; }\n.px__ph { display: grid; place-items: center; height: 100%; margin: 0; opacity: 0.7; }\n.px__cap { margin: 0; padding: 12px var(--theme-padding-x, 16px); font-size: 0.875rem; letter-spacing: 0.04em; }\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .px__img { animation: px-drift linear both; animation-timeline: view(); animation-range: cover; }\n    @keyframes px-drift { from { transform: translateY(calc(var(--px-shift, 10%) * -1)); } to { transform: translateY(var(--px-shift, 10%)); } }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_parallax_media\",\n  \"name\": \"Photo band\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n    { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" },\n    { \"type\": \"text\", \"id\": \"caption\", \"label\": \"Caption\", \"default\": \"The yard at first light\" },\n    { \"type\": \"range\", \"id\": \"height\", \"label\": \"Height\", \"min\": 40, \"max\": 100, \"step\": 5, \"unit\": \"%\", \"default\": 70 },\n    { \"type\": \"range\", \"id\": \"strength\", \"label\": \"Drift\", \"min\": 0, \"max\": 12, \"step\": 1, \"unit\": \"%\", \"default\": 8 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_pin_gallery.storelib",
  "source": "{# example\ntitle: Pinned sideways collection (motion islands)\nsummary: The section pins and a row of large product or project panels runs sideways as the visitor scrolls down (the pin-horizontal motion island), with a number and caption per panel; phones and reduced motion get a native swipe with snap points (or a stack), so every panel is always reachable.\ntags: pinned, pin, horizontal scroll, sideways, scroll gallery, collection, lookbook, portfolio, projects, motion islands, scroll storytelling, awwwards\n#}\n<template>\n<section class=\"pg\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }};\">\n  <div class=\"pg__run\" data-storelib-motion=\"pin-horizontal\" data-motion-speed=\"{{ settings.motion_speed }}\" data-motion-direction=\"{{ settings.motion_direction }}\" data-motion-mobile=\"{{ settings.motion_mobile }}\">\n    <div class=\"pg__stage\" data-motion-stage>\n      <div class=\"pg__track\" data-motion-track>\n        <header class=\"pg__intro\">\n          <h2 class=\"pg__h\">{{ settings.heading }}</h2>\n          {% if settings.text %}<p class=\"pg__text\">{{ settings.text }}</p>{% endif %}\n        </header>\n        {% for block in section.blocks %}\n        <figure class=\"pg__panel\" data-block-id=\"{{ block.id }}\">\n          {% if block.settings.image %}<img class=\"pg__img\" src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"1200\" height=\"1500\" loading=\"lazy\">{% elsif page.in_editor %}<span class=\"pg__ph\">Add a photo</span>{% endif %}\n          <figcaption class=\"pg__cap\"><span class=\"pg__n\">{{ forloop.index }}</span>{{ block.settings.caption }}</figcaption>\n        </figure>\n        {% endfor %}\n      </div>\n    </div>\n  </div>\n</section>\n</template>\n\n<style scoped>\n.pg { background: var(--s-bg); color: var(--s-text); padding-block: 48px; }\n.pg__track { display: flex; gap: clamp(12px, 2vw, 28px); padding-inline: var(--theme-padding-x, 16px); align-items: end; }\n.pg__intro { flex: none; width: min(80vw, 420px); align-self: center; }\n.pg__h { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2.25rem, 1.4rem + 4vw, 5.5rem); line-height: 0.92; letter-spacing: -0.03em; color: var(--s-heading); }\n.pg__text { margin: 18px 0 0; max-width: 34ch; line-height: 1.55; }\n.pg__panel { flex: none; width: min(78vw, 460px); margin: 0; }\n.pg__panel:nth-child(odd) { width: min(70vw, 380px); }\n.pg__img, .pg__ph { display: block; width: 100%; aspect-ratio: 4 / 5; object-fit: cover; }\n.pg__ph { display: grid; place-items: center; border: 1px dashed var(--s-border); }\n.pg__cap { display: flex; gap: 12px; align-items: baseline; margin-top: 12px; font-size: 0.9375rem; }\n.pg__n { font-variant-numeric: tabular-nums; color: var(--s-accent); }\n.pg__panel:focus-within { outline: 2px solid var(--s-accent); outline-offset: 4px; }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_pin_gallery\",\n  \"name\": \"Pinned sideways collection\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"The spring run\" },\n    { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"Six pieces cut from deadstock wool, made in batches of forty.\" },\n    { \"type\": \"range\", \"id\": \"motion_speed\", \"label\": \"Scroll distance\", \"min\": 0.5, \"max\": 2, \"step\": 0.1, \"unit\": \"x\", \"default\": 1 },\n    { \"type\": \"select\", \"id\": \"motion_direction\", \"label\": \"Direction\", \"options\": [{ \"value\": \"left\", \"label\": \"Right to left\" }, { \"value\": \"right\", \"label\": \"Left to right\" }], \"default\": \"left\" },\n    { \"type\": \"select\", \"id\": \"motion_mobile\", \"label\": \"On phones\", \"options\": [{ \"value\": \"swipe\", \"label\": \"Swipe\" }, { \"value\": \"stack\", \"label\": \"Stack\" }], \"default\": \"swipe\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"panel\", \"name\": \"Panel\", \"settings\": [\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" },\n      { \"type\": \"text\", \"id\": \"caption\", \"label\": \"Caption\", \"default\": \"Overshirt in moss\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Pinned sideways collection\", \"blocks\": [{ \"type\": \"panel\", \"settings\": { \"caption\": \"Overshirt in moss\" } }, { \"type\": \"panel\", \"settings\": { \"caption\": \"Wide trouser in slate\" } }, { \"type\": \"panel\", \"settings\": { \"caption\": \"Field jacket in rust\" } }, { \"type\": \"panel\", \"settings\": { \"caption\": \"Knit vest in oat\" } }, { \"type\": \"panel\", \"settings\": { \"caption\": \"Work shirt in ink\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_scroll_reveal.storelib",
  "source": "{# example\ntitle: Scroll reveal chapters\nsummary: Chapters that fade and rise into place as they scroll into view, with CSS scroll-driven animation only, travelling as far as the site's motion feel says (--t-motion-distance) times the strength the creator sets; visible and still without support, with reduced motion or set to still.\ntags: scroll, reveal, fade, view-timeline, animation-timeline, chapters, story, motion, stagger, reveal on scroll, motion tier\n#}\n<template>\n<section class=\"rv\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--m-k: calc({{ settings.motion_strength }} / 100); --s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  {% if settings.heading %}<h2 class=\"rv__h\">{{ settings.heading }}</h2>{% endif %}\n  <ol class=\"rv__list\">\n    {% for block in section.blocks %}\n      <li class=\"rv__item\" data-block-id=\"{{ block.id }}\">\n        <span class=\"rv__num\">{{ forloop.index | prepend: '0' | slice: -2, 2 }}</span>\n        <div class=\"rv__body\">\n          <h3 class=\"rv__title\">{{ block.settings.title }}</h3>\n          {% if block.settings.text %}<div class=\"rv__text\">{{ block.settings.text }}</div>{% endif %}\n        </div>\n      </li>\n    {% else %}\n      {% if page.in_editor %}<li class=\"rv__empty\">Add chapters in the sidebar</li>{% endif %}\n    {% endfor %}\n  </ol>\n</section>\n</template>\n\n<style scoped>\n.rv { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 20px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.rv__h { margin: 0 0 clamp(32px, 6vw, 72px); max-width: 18ch; font-family: var(--theme-font-heading), serif; font-size: clamp(2rem, 1.4rem + 3vw, 4.2rem); line-height: 0.98; letter-spacing: -0.025em; font-weight: 500; color: var(--s-heading); }\n.rv__list { list-style: none; margin: 0; padding: 0; }\n.rv__item { display: grid; grid-template-columns: 3.5rem 1fr; gap: 16px; padding: 28px 0; border-top: 1px solid var(--s-border); }\n.rv__num { font-family: var(--theme-font-accent, var(--theme-font-body)), monospace; font-size: 0.8125rem; letter-spacing: 0.12em; color: var(--s-accent); font-variant-numeric: tabular-nums; }\n.rv__title { margin: 0 0 8px; font-family: var(--theme-font-heading), serif; font-size: clamp(1.4rem, 1.1rem + 1.4vw, 2.2rem); line-height: 1.05; font-weight: 500; color: var(--s-heading); }\n.rv__text { max-width: 60ch; font-size: 1.0625rem; line-height: 1.6; }\n.rv__empty { padding: 24px 0; opacity: 0.7; }\n@container (max-width: 600px) { .rv__list { --m-phone: 0.6; } }\n@container (min-width: 760px) { .rv__item { grid-template-columns: 8rem minmax(0, 1fr); padding: 40px 0; } }\n/* Motion is an extra: only where the browser ties it to scroll, and only for people who have not asked for less. */\n@supports (animation-timeline: view()) {\n  @media (prefers-reduced-motion: no-preference) {\n    .rv:not([data-motion=\"off\"]) .rv__item { animation: rv-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }\n    @keyframes rv-rise { from { opacity: 0; transform: translateY(calc(var(--t-motion-distance, 24px) * 1.3 * var(--m-k, 1) * var(--m-phone, 1))); } to { opacity: 1; transform: none; } }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_scroll_reveal\",\n  \"name\": \"Chapters that reveal\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"How a commission comes together\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Motion strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 }\n  ],\n  \"blocks\": [\n    { \"type\": \"chapter\", \"name\": \"Chapter\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"A first conversation\" },\n      { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"What you need, where it will live, and when.\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Chapters that reveal\", \"blocks\": [{ \"type\": \"chapter\", \"settings\": { \"title\": \"A first conversation\", \"text\": \"What you need, where it will live, and when.\" } }, { \"type\": \"chapter\", \"settings\": { \"title\": \"Sketches\", \"text\": \"Two or three directions on paper before anything is made.\" } }, { \"type\": \"chapter\", \"settings\": { \"title\": \"Making\", \"text\": \"The piece is made, with photos along the way.\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_scrub_story.storelib",
  "source": "{# example\ntitle: Scroll scrubbed product story (motion islands)\nsummary: A pinned stage whose frames (8 to 60 of the creator's own photos, one block each) are scrubbed by the scroll with the scroll-scrub motion island, while a caption per chapter fades in from the island's --motion-progress; reduced motion and phones set to still show one chosen frame in normal flow with every caption listed.\ntags: scroll scrub, scrub, image sequence, frame by frame, product turning, pinned, sticky, scroll storytelling, video scrub, motion islands, cinematic, awwwards\n#}\n<template>\n<section class=\"ss\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }};\" aria-label=\"{{ settings.heading }}\">\n  <h2 class=\"ss__h\">{{ settings.heading }}</h2>\n  {% if section.blocks.size > 0 %}\n  <div class=\"ss__scrub\" data-storelib-motion=\"scroll-scrub\" data-motion-length=\"{{ settings.motion_length }}\" data-motion-still=\"{{ settings.motion_still }}\" data-motion-mobile=\"{{ settings.motion_mobile }}\">\n    <div class=\"ss__stage\" data-motion-stage>\n      {% for block in section.blocks %}{% if block.settings.image %}<img class=\"ss__frame\" data-motion-frame data-block-id=\"{{ block.id }}\" src=\"{{ block.settings.image | asset }}\" alt=\"{% if forloop.first %}{{ settings.image_alt }}{% endif %}\" width=\"1600\" height=\"900\">{% endif %}{% endfor %}\n      <ol class=\"ss__caps\">\n        {% for block in section.blocks %}{% if block.settings.caption %}<li class=\"ss__cap\" style=\"--i: {{ forloop.index0 }}; --n: {{ section.blocks.size }};\">{{ block.settings.caption }}</li>{% endif %}{% endfor %}\n      </ol>\n    </div>\n  </div>\n  {% elsif page.in_editor %}\n  <p class=\"ss__empty\">Add frames in the sidebar, one photo each, in order</p>\n  {% endif %}\n</section>\n</template>\n\n<style scoped>\n.ss { background: var(--s-bg); color: var(--s-text); }\n.ss__h { margin: 0; padding: 72px var(--theme-padding-x, 16px) 32px; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2rem, 1.2rem + 3.6vw, 4.5rem); line-height: 0.95; letter-spacing: -0.03em; color: var(--s-heading); max-width: 18ch; }\n.ss__stage { position: relative; aspect-ratio: 16 / 9; max-height: 100svh; width: 100%; }\n.ss__frame { position: absolute; inset: 0; }\n.ss__caps { margin: 0; padding: 20px var(--theme-padding-x, 16px); list-style: none; display: grid; gap: 10px; }\n.ss__cap { font-size: 1.0625rem; line-height: 1.45; max-width: 36ch; }\n.ss__empty { padding: 16px; opacity: 0.7; }\n/* While the island runs: the captions sit over the stage, one at a time, from the scroll's progress. */\n@media (prefers-reduced-motion: no-preference) {\n  .ss__scrub[data-motion-ready] .ss__caps { position: absolute; left: 0; bottom: 0; padding-bottom: 40px; }\n  .ss__scrub[data-motion-ready] .ss__cap { grid-area: 1 / 1; color: #fff; text-shadow: 0 1px 12px rgb(0 0 0 / 0.45); font-size: clamp(1.25rem, 1rem + 1.2vw, 2rem); --d: calc(var(--motion-progress, 0) * var(--n) - var(--i) - 0.5); opacity: clamp(0, calc(1 - max(var(--d), calc(var(--d) * -1)) * 2.2), 1); }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_scrub_story\",\n  \"name\": \"Scroll scrubbed story\",\n  \"category\": \"image\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"From billet to case\" },\n    { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"What the frames show\", \"default\": \"\" },\n    { \"type\": \"range\", \"id\": \"motion_length\", \"label\": \"Scroll length\", \"min\": 1, \"max\": 6, \"step\": 0.5, \"unit\": \"screens\", \"default\": 3 },\n    { \"type\": \"select\", \"id\": \"motion_still\", \"label\": \"Still frame\", \"options\": [{ \"value\": \"first\", \"label\": \"First\" }, { \"value\": \"middle\", \"label\": \"Middle\" }, { \"value\": \"last\", \"label\": \"Last\" }], \"default\": \"last\" },\n    { \"type\": \"select\", \"id\": \"motion_mobile\", \"label\": \"On phones\", \"options\": [{ \"value\": \"scrub\", \"label\": \"Scrub, shorter\" }, { \"value\": \"still\", \"label\": \"Still frame\" }], \"default\": \"scrub\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ],\n  \"blocks\": [\n    { \"type\": \"frame\", \"name\": \"Frame\", \"settings\": [\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n      { \"type\": \"text\", \"id\": \"caption\", \"label\": \"Caption (optional)\", \"default\": \"\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Scroll scrubbed story\", \"blocks\": [{ \"type\": \"frame\", \"settings\": { \"caption\": \"A solid bar of 6061 aluminium\" } }, { \"type\": \"frame\", \"settings\": { \"caption\": \"Milled over eleven hours\" } }, { \"type\": \"frame\", \"settings\": { \"caption\": \"Bead blasted and anodised\" } }, { \"type\": \"frame\", \"settings\": { \"caption\": \"Checked by hand, then signed\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_site_footer.storelib",
  "source": "{# example\ntitle: Big type footer with sign up, menus and locale switches\nsummary: A free site's own footer: the name set huge, a newsletter sign up that joins the creator's Subscribers, two menu columns from the site's own menus, language and currency switches through the page's hooks (hidden when the site has one), and the year and policies line.\ntags: footer, newsletter, signup, subscribe, menus, locale, currency, language, big type, own chrome, site footer\n#}\n<template>\n<footer class=\"sf\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }};\">\n  <div class=\"sf__top\">\n    <form class=\"sf__form\" data-storelib-form=\"subscribe\">\n      <label class=\"sf__label\" for=\"{{ section.id }}-email\">{{ settings.signup_label }}</label>\n      <div class=\"sf__row\">\n        <input class=\"sf__input\" id=\"{{ section.id }}-email\" name=\"email\" type=\"email\" inputmode=\"email\" autocomplete=\"email\" maxlength=\"254\" placeholder=\"{{ settings.email_placeholder }}\" required>\n        <button class=\"sf__btn\" type=\"submit\">{{ settings.signup_button }}</button>\n      </div>\n      <p class=\"sf__done\" data-storelib-success hidden>{{ settings.signup_success }}</p>\n    </form>\n    <nav class=\"sf__cols\" aria-label=\"{{ settings.nav_label }}\">\n      {% if settings.menu_one.links.size > 0 %}<div class=\"sf__col\"><p class=\"sf__col-h\">{{ settings.menu_one.title }}</p><ul>{% for link in settings.menu_one.links %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul></div>{% endif %}\n      {% if settings.menu_two.links.size > 0 %}<div class=\"sf__col\"><p class=\"sf__col-h\">{{ settings.menu_two.title }}</p><ul>{% for link in settings.menu_two.links %}<li><a href=\"{{ link.url }}\">{{ link.title }}</a></li>{% endfor %}</ul></div>{% endif %}\n    </nav>\n  </div>\n  <div class=\"sf__prefs\">\n    <details class=\"sf__pick\" data-storelib-locale-list>\n      <summary class=\"sf__pick-btn\">{{ settings.language_label }}: <span data-storelib-locale-current></span></summary>\n      <div class=\"sf__menu\"><button class=\"sf__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n    </details>\n    <details class=\"sf__pick\" data-storelib-currency-list>\n      <summary class=\"sf__pick-btn\">{{ settings.currency_label }}: <span data-storelib-currency-current></span></summary>\n      <div class=\"sf__menu\"><button class=\"sf__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n    </details>\n  </div>\n  <p class=\"sf__name\" aria-hidden=\"true\">{{ shop.name | default: settings.brand }}</p>\n  <div class=\"sf__base\"><span>{{ settings.copyright }}</span>{% if settings.base_link_url and settings.base_link_label %}<a href=\"{{ settings.base_link_url | url }}\">{{ settings.base_link_label }}</a>{% endif %}</div>\n</footer>\n</template>\n\n<style scoped>\n.sf { container-type: inline-size; padding: clamp(48px, 8vw, 96px) var(--theme-padding-x, 16px) 20px; background: var(--s-bg); color: var(--s-text); overflow: hidden; }\n.sf__top { display: grid; gap: 40px; }\n.sf__label { display: block; margin-bottom: 12px; font-family: var(--theme-font-heading), serif; font-size: clamp(1.5rem, 1.1rem + 1.8vw, 2.5rem); line-height: 1.05; letter-spacing: -0.02em; color: var(--s-heading); }\n.sf__row { display: flex; gap: 8px; max-width: 520px; }\n.sf__input { flex: 1; min-width: 0; min-height: 48px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; }\n.sf__btn { min-height: 48px; padding: 0 18px; border: 0; background: var(--s-btn); color: var(--s-btn-text); font: inherit; cursor: pointer; }\n.sf__done { margin: 10px 0 0; }\n.sf__cols { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }\n.sf__col-h { margin: 0 0 10px; font-size: 0.9375rem; font-weight: 600; color: inherit; }\n.sf__col ul { margin: 0; padding: 0; list-style: none; }\n.sf__col a { display: inline-block; padding: 6px 0; color: inherit; text-decoration: none; }\n.sf__col a:hover, .sf__col a:focus-visible { text-decoration: underline; text-underline-offset: 4px; }\n.sf__prefs { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 40px; }\n.sf__pick { position: relative; }\n.sf__pick-btn { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); cursor: pointer; list-style: none; font-size: 0.875rem; }\n.sf__pick-btn::-webkit-details-marker { display: none; }\n.sf__menu { position: absolute; bottom: calc(100% + 6px); left: 0; display: grid; min-width: 180px; padding: 6px; background: var(--s-bg); border: 1px solid var(--s-border); }\n.sf__opt { min-height: 44px; padding: 0 10px; border: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; }\n.sf__opt[aria-current=\"true\"] { color: var(--s-accent); }\n.sf__name { margin: clamp(32px, 6vw, 72px) 0 0; font-family: var(--theme-font-heading), serif; font-size: clamp(3.5rem, 0.5rem + 15vw, 16rem); line-height: 0.8; letter-spacing: -0.05em; font-weight: 600; color: var(--s-heading); white-space: nowrap; }\n.sf__base { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; padding-top: 16px; margin-top: 16px; border-top: 1px solid var(--s-border); font-size: 0.8125rem; }\n.sf__base a { color: inherit; }\n.sf :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@container (min-width: 820px) { .sf__top { grid-template-columns: 7fr 5fr; align-items: start; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_site_footer\",\n  \"name\": \"Site footer\",\n  \"kind\": \"footer\",\n  \"enabled_on\": { \"groups\": [\"footer\"] },\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"signup_label\", \"label\": \"Sign up heading\", \"default\": \"A letter when the new pieces are out\" },\n    { \"type\": \"text\", \"id\": \"email_placeholder\", \"label\": \"Email hint\", \"default\": \"Email address\" },\n    { \"type\": \"text\", \"id\": \"signup_button\", \"label\": \"Sign up button\", \"default\": \"Sign up\" },\n    { \"type\": \"text\", \"id\": \"signup_success\", \"label\": \"After signing up\", \"default\": \"Thanks. Check your inbox.\" },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menus name (read aloud)\", \"default\": \"Footer\" },\n    { \"type\": \"link_list\", \"id\": \"menu_one\", \"label\": \"First menu\", \"default\": \"main-menu\" },\n    { \"type\": \"link_list\", \"id\": \"menu_two\", \"label\": \"Second menu\", \"default\": \"footer\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency\", \"default\": \"Currency\" },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no shop name\", \"default\": \"Studio\" },\n    { \"type\": \"text\", \"id\": \"copyright\", \"label\": \"Bottom line\", \"default\": \"Made in Leeds\" },\n    { \"type\": \"text\", \"id\": \"base_link_label\", \"label\": \"Bottom link\", \"default\": \"Contact\" },\n    { \"type\": \"url\", \"id\": \"base_link_url\", \"label\": \"Bottom link goes to\", \"default\": \"/contact\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_site_header.storelib",
  "source": "{# example\ntitle: Site header with mega menu, own search and own cart drawer\nsummary: A free site's own header: logo from Theme settings, the Main menu with sub links as popover mega panels on wide screens, a full screen mobile menu popover, its own search window and its own cart drawer through the page's hooks (no built-in drawer), language and currency switches; Escape, light dismiss and keyboard come from the popover API.\ntags: header, navigation, mega menu, mobile menu, hamburger, cart drawer, search panel, popover, locale, currency, language, own chrome, site header\n#}\n<template>\n<header class=\"sh\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-btn: {{ scheme.primary_btn_bg }}; --s-btn-text: {{ scheme.primary_btn_text }};\">\n  <div class=\"sh__bar\">\n    <a class=\"sh__logo\" href=\"{{ routes.root_url }}\">{% if theme.logo.url %}<img src=\"{{ theme.logo.url }}\" alt=\"{{ shop.name }}\" width=\"{{ settings.logo_width }}\" height=\"40\">{% else %}{{ shop.name | default: settings.brand }}{% endif %}</a>\n\n    <nav class=\"sh__nav\" aria-label=\"{{ settings.nav_label }}\">\n      <ul class=\"sh__links\">\n        {% for link in settings.menu.links %}\n          <li class=\"sh__li\">\n            {% if link.links.size > 0 %}\n              <button class=\"sh__top\" type=\"button\" popovertarget=\"mm-{{ section.id }}-{{ forloop.index }}\">{{ link.title }}</button>\n              <div class=\"sh__mega\" id=\"mm-{{ section.id }}-{{ forloop.index }}\" popover>\n                <a class=\"sh__mega-all\" href=\"{{ link.url }}\">{{ link.title }}</a>\n                <ul class=\"sh__mega-list\">\n                  {% for child in link.links %}<li><a class=\"sh__mega-link\" href=\"{{ child.url }}\">{{ child.title }}</a></li>{% endfor %}\n                </ul>\n              </div>\n            {% else %}\n              <a class=\"sh__top\" href=\"{{ link.url }}\">{{ link.title }}</a>\n            {% endif %}\n          </li>\n        {% endfor %}\n      </ul>\n    </nav>\n\n    <div class=\"sh__tools\">\n      <a class=\"sh__tool\" href=\"{{ routes.search_url }}\" data-storelib-search>{{ settings.search_label }}</a>\n      <a class=\"sh__tool\" href=\"{{ routes.cart_url }}\" data-storelib-cart>{{ settings.cart_label }} <span class=\"sh__count\" data-storelib-cart-count></span></a>\n      <button class=\"sh__tool sh__burger\" type=\"button\" popovertarget=\"mob-{{ section.id }}\">{{ settings.menu_label }}</button>\n    </div>\n  </div>\n\n  <div class=\"sh__mobile\" id=\"mob-{{ section.id }}\" popover>\n    <button class=\"sh__close\" type=\"button\" popovertarget=\"mob-{{ section.id }}\" popovertargetaction=\"hide\">{{ settings.close_label }}</button>\n    <nav aria-label=\"{{ settings.nav_label }}\">\n      <ul class=\"sh__mlist\">\n        {% for link in settings.menu.links %}\n          <li>\n            <a class=\"sh__mlink\" href=\"{{ link.url }}\">{{ link.title }}</a>\n            {% if link.links.size > 0 %}<ul class=\"sh__msub\">{% for child in link.links %}<li><a href=\"{{ child.url }}\">{{ child.title }}</a></li>{% endfor %}</ul>{% endif %}\n          </li>\n        {% endfor %}\n      </ul>\n    </nav>\n    <div class=\"sh__prefs\">\n      <div class=\"sh__pref\" data-storelib-locale-list><span class=\"sh__pref-label\">{{ settings.language_label }}</span><button class=\"sh__opt\" type=\"button\" data-storelib-locale-option hidden><span data-option-label></span></button></div>\n      <div class=\"sh__pref\" data-storelib-currency-list><span class=\"sh__pref-label\">{{ settings.currency_label }}</span><button class=\"sh__opt\" type=\"button\" data-storelib-currency-option hidden><span data-option-label></span></button></div>\n    </div>\n  </div>\n\n  <div class=\"sh__search\" data-storelib-search-panel role=\"dialog\" aria-label=\"{{ settings.search_label }}\">\n    <div class=\"sh__search-in\">\n      <input class=\"sh__input\" type=\"search\" data-storelib-search-input placeholder=\"{{ settings.search_placeholder }}\" aria-label=\"{{ settings.search_label }}\">\n      <button class=\"sh__close\" type=\"button\" data-storelib-search-close>{{ settings.close_label }}</button>\n      <p class=\"sh__state\" data-storelib-search-loading hidden>{{ settings.loading_text }}</p>\n      <p class=\"sh__state\" data-storelib-search-empty hidden>{{ settings.no_results_text }}</p>\n      <ul class=\"sh__results\" data-storelib-search-results>\n        <li class=\"sh__result\" data-storelib-search-result hidden><a class=\"sh__result-link\" data-result-url><img data-result-image alt=\"\" width=\"56\" height=\"70\"><span data-result-title></span><span class=\"sh__result-price\" data-result-price></span></a></li>\n      </ul>\n    </div>\n  </div>\n\n  <aside class=\"sh__cart\" data-storelib-cart-panel aria-label=\"{{ settings.cart_label }}\">\n    <div class=\"sh__cart-head\"><p class=\"sh__cart-title\">{{ settings.cart_label }}</p><button class=\"sh__close\" type=\"button\" data-storelib-cart-close>{{ settings.close_label }}</button></div>\n    <p class=\"sh__state\" data-storelib-cart-empty>{{ settings.empty_text }}</p>\n    <ul class=\"sh__lines\" data-storelib-cart-lines>\n      <li class=\"sh__line\" data-storelib-cart-line hidden>\n        <img data-line-image alt=\"\" width=\"64\" height=\"80\">\n        <div class=\"sh__line-main\"><a data-line-url><span data-line-title></span></a><span class=\"sh__line-var\" data-line-variant></span>\n          <div class=\"sh__qty\"><button type=\"button\" data-line-dec aria-label=\"{{ settings.less_label }}\">-</button><span data-line-qty></span><button type=\"button\" data-line-inc aria-label=\"{{ settings.more_label }}\">+</button><button class=\"sh__remove\" type=\"button\" data-line-remove>{{ settings.remove_label }}</button></div>\n        </div>\n        <span data-line-price></span>\n      </li>\n    </ul>\n    <div class=\"sh__cart-foot\" data-storelib-cart-filled>\n      <p class=\"sh__sub\"><span>{{ settings.subtotal_label }}</span><span data-storelib-cart-subtotal></span></p>\n      <button class=\"sh__checkout\" type=\"button\" data-storelib-checkout>{{ settings.checkout_label }}</button>\n    </div>\n  </aside>\n</header>\n</template>\n\n<style scoped>\n.sh { position: relative; z-index: 20; background: var(--s-bg); color: var(--s-text); border-bottom: 1px solid var(--s-border); }\n.sh__bar { display: flex; align-items: center; gap: 16px; min-height: 64px; padding: 0 var(--theme-padding-x, 16px); }\n.sh__logo { margin-right: auto; font-family: var(--theme-font-heading), serif; font-size: 1.375rem; letter-spacing: -0.02em; color: var(--s-heading); text-decoration: none; }\n.sh__logo img { display: block; height: auto; max-height: 40px; width: auto; }\n.sh__nav { display: none; }\n.sh__links { display: flex; gap: 4px; margin: 0; padding: 0; list-style: none; }\n.sh__top { display: inline-flex; align-items: center; min-height: 44px; padding: 0 12px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.9375rem; text-decoration: none; cursor: pointer; }\n.sh__top:hover, .sh__top:focus-visible { color: var(--s-accent); }\n.sh__mega { position: fixed; inset: 64px 0 auto; margin: 0; width: 100%; max-width: none; padding: 32px var(--theme-padding-x, 16px) 40px; border: 0; border-bottom: 1px solid var(--s-border); background: var(--s-bg); color: var(--s-text); }\n.sh__mega-all { display: inline-block; margin-bottom: 20px; font-family: var(--theme-font-heading), serif; font-size: clamp(1.5rem, 1rem + 2vw, 2.5rem); letter-spacing: -0.02em; color: var(--s-heading); }\n.sh__mega-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(200px, 100%), 1fr)); gap: 8px 24px; margin: 0; padding: 0; list-style: none; }\n.sh__mega-link { display: block; padding: 8px 0; color: inherit; text-decoration: none; }\n.sh__tools { display: flex; align-items: center; gap: 4px; }\n.sh__tool { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0 10px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.875rem; letter-spacing: 0.04em; text-transform: uppercase; text-decoration: none; cursor: pointer; }\n.sh__count[data-count=\"0\"] { display: none; }\n.sh__count { min-width: 1.5em; padding: 0 4px; background: var(--s-accent); color: var(--s-bg); text-align: center; font-variant-numeric: tabular-nums; }\n.sh__mobile { position: fixed; inset: 0; width: 100%; height: 100%; max-width: none; max-height: none; margin: 0; padding: 20px var(--theme-padding-x, 16px); border: 0; background: var(--s-bg); color: var(--s-text); overflow-y: auto; }\n.sh__close { display: inline-flex; align-items: center; min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.sh__mlist { margin: 32px 0; padding: 0; list-style: none; }\n.sh__mlink { display: block; padding: 10px 0; font-family: var(--theme-font-heading), serif; font-size: clamp(2rem, 1.4rem + 4vw, 3.5rem); line-height: 1; letter-spacing: -0.03em; color: var(--s-heading); text-decoration: none; }\n.sh__msub { margin: 0 0 12px; padding: 0; list-style: none; }\n.sh__msub a { display: block; padding: 8px 0; color: inherit; }\n.sh__prefs { display: grid; gap: 12px; padding-top: 20px; border-top: 1px solid var(--s-border); }\n.sh__pref { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }\n.sh__pref-label { font-size: 0.875rem; font-weight: 500; }\n.sh__opt { min-height: 44px; padding: 0 12px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.sh__opt[aria-current=\"true\"] { border-color: currentColor; }\n.sh__search, .sh__cart { position: fixed; z-index: 30; background: var(--s-bg); color: var(--s-text); visibility: hidden; opacity: 0; transition: opacity 200ms ease, transform 280ms cubic-bezier(0.32, 0.72, 0, 1), visibility 0s linear 280ms; }\n.sh__search { inset: 0 0 auto; padding: 16px var(--theme-padding-x, 16px) 32px; border-bottom: 1px solid var(--s-border); transform: translateY(-16px); max-height: 100svh; overflow-y: auto; }\n.sh__search-in { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 12px; max-width: 960px; margin: 0 auto; }\n.sh__input { min-height: 52px; padding: 0 4px; border: 0; border-bottom: 2px solid currentColor; background: none; color: inherit; font: inherit; font-size: clamp(1.25rem, 1rem + 1.2vw, 2rem); }\n.sh__state { grid-column: 1 / -1; margin: 0; }\n.sh__results { grid-column: 1 / -1; margin: 0; padding: 0; list-style: none; }\n.sh__result-link { display: grid; grid-template-columns: 56px minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 10px 0; color: inherit; text-decoration: none; border-bottom: 1px solid var(--s-border); }\n.sh__result-link img { width: 56px; height: 70px; object-fit: cover; }\n.sh__cart { inset: 0 0 0 auto; display: flex; flex-direction: column; width: min(420px, 100%); padding: 16px 20px; border-left: 1px solid var(--s-border); transform: translateX(100%); }\n.sh__cart-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }\n.sh__cart-title { margin: 0; font-family: var(--theme-font-heading), serif; font-size: 1.5rem; color: var(--s-heading); }\n.sh__lines { flex: 1; margin: 0; padding: 0; list-style: none; overflow-y: auto; }\n.sh__line { display: grid; grid-template-columns: 64px minmax(0, 1fr) auto; gap: 12px; padding: 14px 0; border-bottom: 1px solid var(--s-border); }\n.sh__line img { width: 64px; height: 80px; object-fit: cover; }\n.sh__line-main a { color: inherit; }\n.sh__line-var { display: block; font-size: 0.875rem; }\n.sh__qty { display: flex; align-items: center; gap: 6px; margin-top: 8px; }\n.sh__qty button { min-width: 44px; min-height: 44px; border: 1px solid var(--s-border); background: none; color: inherit; font: inherit; cursor: pointer; }\n.sh__qty .sh__remove { min-width: 0; padding: 0 10px; border: 0; text-decoration: underline; }\n.sh__cart-foot { padding-top: 16px; }\n.sh__sub { display: flex; justify-content: space-between; margin: 0 0 12px; font-variant-numeric: tabular-nums; }\n.sh__checkout { width: 100%; min-height: 52px; border: 0; background: var(--s-btn); color: var(--s-btn-text); font: inherit; letter-spacing: 0.04em; cursor: pointer; }\n/* The page sets data-open on its own panels (search and cart) and toggles them with Escape and the close buttons. */\n.sh__search[data-open=\"true\"], .sh__cart[data-open=\"true\"] { visibility: visible; opacity: 1; transform: none; transition-delay: 0s; }\n.sh :focus-visible { outline: 2px solid var(--s-accent); outline-offset: 2px; }\n@media (min-width: 900px) {\n  .sh__nav { display: block; }\n  .sh__burger { display: none; }\n}\n@media (prefers-reduced-motion: reduce) { .sh__search, .sh__cart { transition: none; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_site_header\",\n  \"name\": \"Site header\",\n  \"kind\": \"header\",\n  \"enabled_on\": { \"groups\": [\"header\"] },\n  \"settings\": [\n    { \"type\": \"link_list\", \"id\": \"menu\", \"label\": \"Menu\", \"default\": \"main-menu\" },\n    { \"type\": \"text\", \"id\": \"brand\", \"label\": \"Name when there is no logo or shop name\", \"default\": \"Home\" },\n    { \"type\": \"range\", \"id\": \"logo_width\", \"label\": \"Logo width\", \"min\": 60, \"max\": 240, \"step\": 4, \"unit\": \"px\", \"default\": 120 },\n    { \"type\": \"text\", \"id\": \"nav_label\", \"label\": \"Menu name (read aloud)\", \"default\": \"Main\" },\n    { \"type\": \"text\", \"id\": \"menu_label\", \"label\": \"Menu button\", \"default\": \"Menu\" },\n    { \"type\": \"text\", \"id\": \"close_label\", \"label\": \"Close button\", \"default\": \"Close\" },\n    { \"type\": \"text\", \"id\": \"search_label\", \"label\": \"Search\", \"default\": \"Search\" },\n    { \"type\": \"text\", \"id\": \"search_placeholder\", \"label\": \"Search hint\", \"default\": \"Search the shop\" },\n    { \"type\": \"text\", \"id\": \"loading_text\", \"label\": \"While searching\", \"default\": \"Looking...\" },\n    { \"type\": \"text\", \"id\": \"no_results_text\", \"label\": \"No results\", \"default\": \"Nothing matches that yet.\" },\n    { \"type\": \"text\", \"id\": \"cart_label\", \"label\": \"Cart\", \"default\": \"Bag\" },\n    { \"type\": \"text\", \"id\": \"empty_text\", \"label\": \"Empty cart\", \"default\": \"Your bag is empty.\" },\n    { \"type\": \"text\", \"id\": \"subtotal_label\", \"label\": \"Subtotal\", \"default\": \"Subtotal\" },\n    { \"type\": \"text\", \"id\": \"checkout_label\", \"label\": \"Checkout button\", \"default\": \"Check out\" },\n    { \"type\": \"text\", \"id\": \"remove_label\", \"label\": \"Remove\", \"default\": \"Remove\" },\n    { \"type\": \"text\", \"id\": \"less_label\", \"label\": \"One less (read aloud)\", \"default\": \"One less\" },\n    { \"type\": \"text\", \"id\": \"more_label\", \"label\": \"One more (read aloud)\", \"default\": \"One more\" },\n    { \"type\": \"text\", \"id\": \"language_label\", \"label\": \"Language\", \"default\": \"Language\" },\n    { \"type\": \"text\", \"id\": \"currency_label\", \"label\": \"Currency\", \"default\": \"Currency\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 },
 {
  "file": "ai_split_text.storelib",
  "source": "{# example\ntitle: Staggered headline\nsummary: A statement whose lines rise into place one after another, split by the creator's own line breaks (one line per block) so no script is needed; complete and still for reduced motion and for screen readers.\ntags: split text, staggered text, text reveal, headline, statement, hero, typography, stagger\n#}\n<template>\n<section class=\"sx\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--m-k: calc({{ settings.motion_strength }} / 100); --s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  {% if settings.label %}<p class=\"sx__label\">{{ settings.label }}</p>{% endif %}\n  <h1 class=\"sx__h sx__h--{{ settings.align }}\">\n    {% for block in section.blocks %}<span class=\"sx__line\" data-block-id=\"{{ block.id }}\" style=\"--d: {{ forloop.index0 }};\"><span class=\"sx__inner{% if block.settings.accent %} sx__inner--accent{% endif %}\">{{ block.settings.line }}</span></span>{% endfor %}\n  </h1>\n  {% if settings.cta_label and settings.cta_url %}<a class=\"sx__cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}\n</section>\n</template>\n\n<style scoped>\n.sx { padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.sx__label { margin: 0 0 20px; font-size: 1rem; font-weight: 500; letter-spacing: 0; color: var(--s-text); }\n.sx__h { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2.75rem, 1.2rem + 7.5vw, 9rem); line-height: 0.9; letter-spacing: -0.04em; font-weight: 600; color: var(--s-heading); }\n.sx__h--offset .sx__line:nth-child(even) { padding-left: 12%; }\n.sx__line { display: block; overflow: hidden; padding-bottom: 0.06em; }\n.sx__inner { display: inline-block; }\n.sx__inner--accent { color: var(--s-accent); }\n.sx__cta { display: inline-block; margin-top: clamp(24px, 4vw, 48px); padding: 14px 22px; background: var(--s-heading); color: var(--s-bg); text-decoration: none; border-radius: 2px; }\n.sx__cta:focus-visible { outline: 2px solid var(--s-accent); outline-offset: 3px; }\n@media (prefers-reduced-motion: no-preference) {\n  .sx:not([data-motion=\"off\"]) .sx__inner { animation: sx-up var(--t-motion-duration, 700ms) var(--t-motion-ease, cubic-bezier(0.2, 0.7, 0, 1)) both; animation-delay: calc(var(--d) * var(--t-motion-stagger, 90ms) + 120ms); }\n  @keyframes sx-up { from { transform: translateY(calc(105% * var(--m-k, 1))); } to { transform: none; } }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_split_text\",\n  \"name\": \"Staggered headline\",\n  \"category\": \"hero\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"Small line above\", \"default\": \"Bakery, Hebden Bridge\" },\n    { \"type\": \"select\", \"id\": \"align\", \"label\": \"Lines\", \"default\": \"offset\", \"options\": [{ \"label\": \"Stepped\", \"value\": \"offset\" }, { \"label\": \"Flush left\", \"value\": \"left\" }] },\n    { \"type\": \"text\", \"id\": \"cta_label\", \"label\": \"Button\", \"default\": \"See today's bakes\" },\n    { \"type\": \"url\", \"id\": \"cta_url\", \"label\": \"Button link\", \"default\": \"/about\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Follow the site\", \"value\": \"site\" }, { \"label\": \"Still\", \"value\": \"off\" }] },\n    { \"type\": \"range\", \"id\": \"motion_strength\", \"label\": \"Motion strength\", \"min\": 0, \"max\": 150, \"step\": 10, \"unit\": \"%\", \"default\": 100 },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 240, \"step\": 8, \"unit\": \"px\", \"default\": 112 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 240, \"step\": 8, \"unit\": \"px\", \"default\": 80 }\n  ],\n  \"blocks\": [\n    { \"type\": \"line\", \"name\": \"Line\", \"limit\": 6, \"settings\": [\n      { \"type\": \"text\", \"id\": \"line\", \"label\": \"Words on this line\", \"default\": \"Bread out\" },\n      { \"type\": \"checkbox\", \"id\": \"accent\", \"label\": \"Accent this line\", \"default\": false }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Staggered headline\", \"blocks\": [{ \"type\": \"line\", \"settings\": { \"line\": \"Bread out\" } }, { \"type\": \"line\", \"settings\": { \"line\": \"at seven,\", \"accent\": true } }, { \"type\": \"line\", \"settings\": { \"line\": \"gone by noon\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_sticky_stack.storelib",
  "source": "{# example\ntitle: Sticky stacked panels\nsummary: Panels that stick and stack on top of each other as the page scrolls, each a little lower than the last, with pure CSS position sticky; a plain list on phones that prefer less motion.\ntags: sticky, stacked cards, stack, scroll, panels, services, steps, layering\n#}\n<template>\n<section class=\"st\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <div class=\"st__head\">\n    {% if settings.label %}<p class=\"st__label\">{{ settings.label }}</p>{% endif %}\n    <h2 class=\"st__h\">{{ settings.heading }}</h2>\n  </div>\n  <ol class=\"st__stack\">\n    {% for block in section.blocks %}\n      <li class=\"st__panel\" data-block-id=\"{{ block.id }}\" style=\"--i: {{ forloop.index0 }};\">\n        <div class=\"st__copy\">\n          <span class=\"st__n\">{{ forloop.index }}</span>\n          <h3 class=\"st__title\">{{ block.settings.title }}</h3>\n          {% if block.settings.text %}<p class=\"st__text\">{{ block.settings.text }}</p>{% endif %}\n          {% if block.settings.link_url and block.settings.link_label %}<a class=\"st__link\" href=\"{{ block.settings.link_url | url }}\">{{ block.settings.link_label }}</a>{% endif %}\n        </div>\n        {% if block.settings.image %}<img class=\"st__img\" src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"800\" height=\"600\" loading=\"lazy\">{% endif %}\n      </li>\n    {% else %}\n      {% if page.in_editor %}<li class=\"st__empty\">Add panels in the sidebar</li>{% endif %}\n    {% endfor %}\n  </ol>\n</section>\n</template>\n\n<style scoped>\n.st { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.st__head { margin-bottom: clamp(24px, 5vw, 56px); }\n.st__label { margin: 0 0 10px; font-size: 1rem; font-weight: 500; letter-spacing: 0; color: var(--s-text); }\n.st__h { margin: 0; max-width: 16ch; font-family: var(--theme-font-heading), serif; font-size: clamp(2rem, 1.3rem + 3.4vw, 4.5rem); line-height: 0.95; letter-spacing: -0.03em; font-weight: 600; color: var(--s-heading); }\n.st__stack { list-style: none; margin: 0; padding: 0; display: grid; gap: 16px; }\n.st__panel { display: grid; gap: 20px; padding: clamp(20px, 4vw, 40px); background: var(--s-bg); border: 1px solid var(--s-border); border-radius: 4px; }\n.st__n { font-variant-numeric: tabular-nums; font-size: 0.875rem; letter-spacing: 0.1em; color: var(--s-accent); }\n.st__title { margin: 8px 0 10px; font-family: var(--theme-font-heading), serif; font-size: clamp(1.5rem, 1.1rem + 1.8vw, 2.6rem); line-height: 1; letter-spacing: -0.02em; font-weight: 600; color: var(--s-heading); }\n.st__text { margin: 0; max-width: 52ch; font-size: 1.0625rem; line-height: 1.6; }\n.st__link { display: inline-block; margin-top: 16px; padding-block: 10px; color: inherit; text-underline-offset: 4px; }\n.st__img { width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; }\n.st__empty { opacity: 0.7; }\n@container (min-width: 760px) {\n  .st__panel { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: end; min-height: 60svh; }\n}\n/* The stack: each panel sticks a little lower than the one before. Only when motion is welcome and there is height for it. */\n@media (prefers-reduced-motion: no-preference) and (min-height: 560px) {\n  .st__panel { position: sticky; top: calc(72px + var(--i) * 18px); }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_sticky_stack\",\n  \"name\": \"Stacked panels\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"Small line above\", \"default\": \"What we do\" },\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Three ways to work together\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 120 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 160 }\n  ],\n  \"blocks\": [\n    { \"type\": \"panel\", \"name\": \"Panel\", \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"One to one\" },\n      { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"Say what happens, how long it takes and who it suits.\" },\n      { \"type\": \"text\", \"id\": \"link_label\", \"label\": \"Link text\", \"default\": \"\" },\n      { \"type\": \"url\", \"id\": \"link_url\", \"label\": \"Link\", \"default\": \"\" },\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Photo\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Photo description\", \"default\": \"\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Stacked panels\", \"blocks\": [{ \"type\": \"panel\", \"settings\": { \"title\": \"One to one\" } }, { \"type\": \"panel\", \"settings\": { \"title\": \"Small groups\" } }, { \"type\": \"panel\", \"settings\": { \"title\": \"Online plan\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_sticky_story.storelib",
  "source": "{# example\ntitle: Sticky storytelling\nsummary: A method told in two to five steps: on a wide screen the picture column stays while the steps pass beside it and each step's picture crossfades in on a named view timeline (position sticky plus timeline-scope, no script, no pinning by JavaScript); on phones, without support or with reduced motion it is plain sequential steps, each with its own picture.\ntags: sticky story, sticky storytelling, scrollytelling, sticky image, process, method, steps, how it works, crossfade, timeline-scope, view-timeline, motion tier\n#}\n<template>\n<section class=\"ss ss--{{ settings.layout }}\" data-motion=\"{{ settings.motion }}\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <div class=\"ss__in\">\n    {% if settings.heading %}<h2 class=\"ss__h\">{{ settings.heading }}</h2>{% endif %}\n    <div class=\"ss__grid\">\n      <div class=\"ss__media\" aria-hidden=\"true\">\n        {% for block in section.blocks %}{% if block.settings.image %}<img class=\"ss__pic\" style=\"animation-timeline: --ss{{ forloop.index }};\" src=\"{{ block.settings.image | asset }}\" alt=\"\" width=\"1200\" height=\"1500\" loading=\"lazy\">{% endif %}{% endfor %}\n      </div>\n      <ol class=\"ss__steps\">\n        {% for block in section.blocks %}\n        <li class=\"ss__step\" data-block-id=\"{{ block.id }}\" style=\"view-timeline-name: --ss{{ forloop.index }};\">\n          <span class=\"ss__n\">{{ forloop.index }}</span>\n          <h3 class=\"ss__title\">{{ block.settings.title }}</h3>\n          {% if block.settings.text %}<p class=\"ss__text\">{{ block.settings.text }}</p>{% endif %}\n          {% if block.settings.image %}<img class=\"ss__inline\" src=\"{{ block.settings.image | asset }}\" alt=\"{{ block.settings.image_alt }}\" width=\"1200\" height=\"1500\" loading=\"lazy\">{% endif %}\n        </li>\n        {% else %}\n        {% if page.in_editor %}<li class=\"ss__step\">Add steps in the sidebar</li>{% endif %}\n        {% endfor %}\n      </ol>\n    </div>\n  </div>\n</section>\n</template>\n\n<style scoped>\n.ss { container-type: inline-size; padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.ss__in { max-width: var(--theme-page-width, 1280px); margin: 0 auto; }\n.ss__h { margin: 0 0 clamp(28px, 5vw, 64px); max-width: 20ch; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2rem, 1.2rem + 3.4vw, 4.4rem); line-height: 0.98; letter-spacing: -0.03em; font-weight: 700; color: var(--s-heading); }\n.ss__grid { display: block; }\n.ss__media { display: none; }\n.ss__steps { list-style: none; margin: 0; padding: 0; display: grid; gap: clamp(40px, 8vw, 72px); }\n.ss__n { display: block; font-size: 0.9375rem; font-variant-numeric: tabular-nums; color: var(--s-accent); }\n.ss__title { margin: 6px 0 10px; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2.5rem); line-height: 1.02; letter-spacing: -0.02em; font-weight: 700; color: var(--s-heading); }\n.ss__text { margin: 0; max-width: 48ch; font-size: 1.0625rem; line-height: 1.6; }\n.ss__inline { display: block; width: 100%; height: auto; aspect-ratio: 4 / 5; object-fit: cover; margin-top: 20px; }\n/* Plain steps on a wider screen: words beside their own picture, never a picture the width of the page. */\n@container (min-width: 760px) {\n  .ss__step { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 4fr); grid-template-rows: auto auto 1fr; column-gap: clamp(24px, 4vw, 64px); align-items: start; }\n  .ss__n, .ss__title, .ss__text { grid-column: 1; }\n  .ss__inline { grid-column: 2; grid-row: 1 / span 3; margin-top: 0; }\n}\n/*\n  The story, only on a wide screen whose browser ties animation to a named\n  view timeline, and only when motion is welcome: the picture column sticks,\n  each step names a timeline, and its picture fades in while that step is in\n  the middle of the screen. Everywhere else the steps above are the layout.\n*/\n@supports (animation-timeline: view()) and (timeline-scope: none) {\n  @media (prefers-reduced-motion: no-preference) {\n    @container (min-width: 860px) {\n      .ss:not([data-motion=\"off\"]) .ss__in { timeline-scope: --ss1, --ss2, --ss3, --ss4, --ss5; }\n      .ss:not([data-motion=\"off\"]) .ss__grid { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); gap: clamp(32px, 5vw, 96px); align-items: start; }\n      .ss--media-right:not([data-motion=\"off\"]) .ss__media { order: 2; }\n      .ss:not([data-motion=\"off\"]) .ss__media { display: block; position: sticky; top: 12svh; max-height: 76svh; aspect-ratio: 4 / 5; overflow: hidden; }\n      .ss:not([data-motion=\"off\"]) .ss__pic { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0; animation: ss-show linear both; animation-range: cover 18% cover 82%; }\n      .ss:not([data-motion=\"off\"]) .ss__inline { display: none; }\n      .ss:not([data-motion=\"off\"]) .ss__step { min-height: 72svh; display: flex; flex-direction: column; justify-content: center; }\n      @keyframes ss-show { 0% { opacity: 0; transform: scale(calc(1 + (var(--t-motion-scale, 1.06) - 1) * 0.5)); } 20%, 80% { opacity: 1; transform: none; } 100% { opacity: 0; transform: none; } }\n    }\n  }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_sticky_story\",\n  \"name\": \"Method, step by step\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"How the twelve weeks run\" },\n    { \"type\": \"header\", \"id\": \"hdr_motion\", \"label\": \"Motion\" },\n    { \"type\": \"select\", \"id\": \"motion\", \"label\": \"Motion\", \"default\": \"site\", \"options\": [{ \"label\": \"Picture stays while steps pass\", \"value\": \"site\" }, { \"label\": \"Plain steps\", \"value\": \"off\" }] },\n    { \"type\": \"select\", \"id\": \"layout\", \"label\": \"Picture side\", \"default\": \"media-left\", \"options\": [{ \"label\": \"Left\", \"value\": \"media-left\" }, { \"label\": \"Right\", \"value\": \"media-right\" }] },\n    { \"type\": \"header\", \"id\": \"hdr_style\", \"label\": \"Style\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 96 }\n  ],\n  \"blocks\": [\n    { \"type\": \"step\", \"name\": \"Step\", \"limit\": 5, \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Title\", \"default\": \"An hour on the floor together\" },\n      { \"type\": \"textarea\", \"id\": \"text\", \"label\": \"Text\", \"default\": \"We test how you move and lift, and agree what the first month is for.\" },\n      { \"type\": \"image_picker\", \"id\": \"image\", \"label\": \"Picture\" },\n      { \"type\": \"text\", \"id\": \"image_alt\", \"label\": \"Picture description\", \"default\": \"\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Method, step by step\", \"blocks\": [{ \"type\": \"step\", \"settings\": { \"title\": \"An hour on the floor together\", \"text\": \"We test how you move and lift, and agree what the first month is for.\" } }, { \"type\": \"step\", \"settings\": { \"title\": \"A plan for the hours you have\", \"text\": \"Three sessions a week, written for your gym or your garage, in the app by Sunday night.\" } }, { \"type\": \"step\", \"settings\": { \"title\": \"A check in every Friday\", \"text\": \"Video of your top sets, a short call, and next week's numbers.\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_tabs.storelib",
  "source": "{# example\ntitle: Tabs without script\nsummary: Tabs built from a native radio group and :has(), so arrow keys move between them, the choice survives without script, and every panel is real text in the page; on a phone the tabs scroll sideways.\ntags: tabs, tab panel, switcher, timetable, menu sections, :has, radio, keyboard\n#}\n<template>\n<section class=\"tb\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }}; --s-border: {{ scheme.border }}; --s-pt: {{ settings.padding_top }}px; --s-pb: {{ settings.padding_bottom }}px;\">\n  <h2 class=\"tb__h\" id=\"tb-{{ section.id }}\">{{ settings.heading }}</h2>\n  {% if section.blocks.size > 0 %}\n  <div class=\"tb__tabs\" role=\"radiogroup\" aria-labelledby=\"tb-{{ section.id }}\">\n    {% for block in section.blocks %}\n      <label class=\"tb__tab\" data-block-id=\"{{ block.id }}\"><input class=\"tb__radio\" type=\"radio\" name=\"tb-{{ section.id }}\" value=\"{{ forloop.index }}\"{% if forloop.first %} checked{% endif %}><span>{{ block.settings.title }}</span></label>\n    {% endfor %}\n  </div>\n  <div class=\"tb__panels\">\n    {% for block in section.blocks %}\n      <div class=\"tb__panel tb__panel--{{ forloop.index }}\">\n        <h3 class=\"tb__ptitle\">{{ block.settings.title }}</h3>\n        <div class=\"tb__body\">{{ block.settings.body | raw }}</div>\n      </div>\n    {% endfor %}\n  </div>\n  {% elsif page.in_editor %}\n  <p class=\"tb__empty\">Add tabs in the sidebar</p>\n  {% endif %}\n</section>\n</template>\n\n<style scoped>\n.tb { padding: calc(var(--s-pt) * var(--theme-spacing-scale, 1)) var(--theme-padding-x, 16px) calc(var(--s-pb) * var(--theme-spacing-scale, 1)); background: var(--s-bg); color: var(--s-text); }\n.tb__h { margin: 0 0 20px; font-family: var(--theme-font-heading), serif; font-size: clamp(1.75rem, 1.2rem + 2.4vw, 3.25rem); line-height: 1; letter-spacing: -0.02em; font-weight: 500; color: var(--s-heading); }\n.tb__tabs { display: flex; gap: 4px; overflow-x: auto; border-bottom: 1px solid var(--s-border); scrollbar-width: none; }\n.tb__tab { position: relative; flex: none; display: inline-flex; align-items: center; min-height: 44px; padding: 0 16px; cursor: pointer; font-size: 0.9375rem; letter-spacing: 0.02em; }\n.tb__radio { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: pointer; }\n.tb__tab:has(.tb__radio:checked) { color: var(--s-heading); box-shadow: inset 0 -2px 0 var(--s-accent); }\n.tb__tab:has(.tb__radio:focus-visible) { outline: 2px solid var(--s-accent); outline-offset: -2px; }\n.tb__panels { padding-top: 28px; }\n.tb__panel { display: none; max-width: 64ch; }\n.tb__ptitle { margin: 0 0 10px; font-size: 1.25rem; font-weight: 600; color: var(--s-heading); }\n.tb__body { font-size: 1.0625rem; line-height: 1.65; }\n.tb__empty { opacity: 0.7; }\n/* Up to eight tabs: the checked radio shows its panel. */\n.tb:has(.tb__radio[value=\"1\"]:checked) .tb__panel--1,\n.tb:has(.tb__radio[value=\"2\"]:checked) .tb__panel--2,\n.tb:has(.tb__radio[value=\"3\"]:checked) .tb__panel--3,\n.tb:has(.tb__radio[value=\"4\"]:checked) .tb__panel--4,\n.tb:has(.tb__radio[value=\"5\"]:checked) .tb__panel--5,\n.tb:has(.tb__radio[value=\"6\"]:checked) .tb__panel--6,\n.tb:has(.tb__radio[value=\"7\"]:checked) .tb__panel--7,\n.tb:has(.tb__radio[value=\"8\"]:checked) .tb__panel--8 { display: block; }\n/* A browser without :has() shows every panel, each under its own title: nothing is lost. */\n@supports not selector(:has(*)) { .tb__panel { display: block; margin-bottom: 24px; } .tb__tabs { display: none; } }\n@media (prefers-reduced-motion: no-preference) {\n  .tb__panel { animation: tb-in 200ms ease both; }\n  @keyframes tb-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }\n}\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_tabs\",\n  \"name\": \"Tabs\",\n  \"category\": \"text\",\n  \"settings\": [\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"The week at the studio\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" },\n    { \"type\": \"range\", \"id\": \"padding_top\", \"label\": \"Top padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 72 },\n    { \"type\": \"range\", \"id\": \"padding_bottom\", \"label\": \"Bottom padding\", \"min\": 0, \"max\": 200, \"step\": 8, \"unit\": \"px\", \"default\": 72 }\n  ],\n  \"blocks\": [\n    { \"type\": \"tab\", \"name\": \"Tab\", \"limit\": 8, \"settings\": [\n      { \"type\": \"text\", \"id\": \"title\", \"label\": \"Tab name\", \"default\": \"Monday\" },\n      { \"type\": \"richtext\", \"id\": \"body\", \"label\": \"Content\", \"default\": \"<p>Write what happens on this day.</p>\" }\n    ] }\n  ],\n  \"presets\": [{ \"name\": \"Tabs\", \"blocks\": [{ \"type\": \"tab\", \"settings\": { \"title\": \"Monday\" } }, { \"type\": \"tab\", \"settings\": { \"title\": \"Wednesday\" } }, { \"type\": \"tab\", \"settings\": { \"title\": \"Saturday\" } }] }]\n}\n</schema>\n"
 },
 {
  "file": "ai_video_hero.storelib",
  "source": "{# example\ntitle: Video hero with a real pause\nsummary: An opening screen over the creator's own muted video with the browser's own controls (so it can always be paused), a poster for slow connections, a heading set large and off centre, one action; no autoplay for people who asked for less motion is left to the controls.\ntags: video hero, hero, video, background video, opening, cinematic, poster\n#}\n<template>\n<section class=\"vh\" data-scheme=\"{{ settings.color_scheme }}\" style=\"--s-bg: {{ scheme.bg }}; --s-text: {{ scheme.text }}; --s-heading: {{ scheme.heading }}; --s-accent: {{ scheme.accent }};\">\n  <div class=\"vh__media\">\n    {% if settings.video %}\n      <video class=\"vh__video\" src=\"{{ settings.video | asset }}\"{% if settings.poster %} poster=\"{{ settings.poster | asset }}\"{% endif %} muted loop playsinline preload=\"metadata\" controls{% if settings.autoplay %} autoplay{% endif %} aria-label=\"{{ settings.video_label }}\"></video>\n    {% elsif settings.poster %}\n      <img class=\"vh__video\" src=\"{{ settings.poster | asset }}\" alt=\"{{ settings.video_label }}\" width=\"1920\" height=\"1080\">\n    {% endif %}\n  </div>\n  <div class=\"vh__copy\">\n    {% if settings.label %}<p class=\"vh__label\">{{ settings.label }}</p>{% endif %}\n    <h1 class=\"vh__h\">{{ settings.heading }}</h1>\n    {% if settings.cta_label and settings.cta_url %}<a class=\"vh__cta\" href=\"{{ settings.cta_url | url }}\">{{ settings.cta_label }}</a>{% endif %}\n  </div>\n</section>\n</template>\n\n<style scoped>\n.vh { position: relative; display: grid; min-height: 88svh; background: var(--s-bg); color: var(--s-text); }\n.vh__media { grid-area: 1 / 1; position: relative; overflow: hidden; }\n.vh__video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }\n.vh__copy { grid-area: 1 / 1; align-self: end; position: relative; z-index: 1; padding: 0 var(--theme-padding-x, 16px) clamp(64px, 10vw, 120px); max-width: 1100px; pointer-events: none; }\n.vh__copy a { pointer-events: auto; }\n.vh__label { margin: 0 0 14px; font-size: 1rem; font-weight: 500; letter-spacing: 0; color: var(--s-text); }\n.vh__h { margin: 0; font-family: var(--theme-font-heading), sans-serif; font-size: clamp(2.75rem, 1.2rem + 7vw, 8.5rem); line-height: 0.88; letter-spacing: -0.035em; font-weight: 600; color: var(--s-heading); text-wrap: balance; }\n.vh__cta { display: inline-block; margin-top: 28px; padding: 14px 22px; background: var(--s-accent); color: var(--s-bg); text-decoration: none; }\n.vh__cta:focus-visible { outline: 2px solid var(--s-text); outline-offset: 3px; }\n@media (min-width: 900px) { .vh__copy { padding-left: 8vw; } }\n</style>\n\n<schema>\n{\n  \"schema_version\": 1,\n  \"type\": \"ai_video_hero\",\n  \"name\": \"Video opening\",\n  \"category\": \"hero\",\n  \"settings\": [\n    { \"type\": \"video_picker\", \"id\": \"video\", \"label\": \"Video\" },\n    { \"type\": \"image_picker\", \"id\": \"poster\", \"label\": \"Still shown while it loads\" },\n    { \"type\": \"text\", \"id\": \"video_label\", \"label\": \"What the video shows\", \"default\": \"The crew rigging lights on set\" },\n    { \"type\": \"checkbox\", \"id\": \"autoplay\", \"label\": \"Play on its own (muted)\", \"default\": true },\n    { \"type\": \"text\", \"id\": \"label\", \"label\": \"Small line above\", \"default\": \"Production company, Glasgow\" },\n    { \"type\": \"text\", \"id\": \"heading\", \"label\": \"Heading\", \"default\": \"Short films for people who make things\" },\n    { \"type\": \"text\", \"id\": \"cta_label\", \"label\": \"Button\", \"default\": \"See the reel\" },\n    { \"type\": \"url\", \"id\": \"cta_url\", \"label\": \"Button link\", \"default\": \"/about\" },\n    { \"type\": \"color_scheme\", \"id\": \"color_scheme\", \"label\": \"Colour scheme\", \"default\": \"site\" }\n  ]\n}\n</schema>\n"
 }
]
